(
  'sol-u1-01-le-piano-et-le-do-central', 'published', 'piano', 'solfege', 'beginner',
  'u1', $cymbra${"en":"The staff and your first notes","fr":"La portée et tes premières notes","es":"El pentagrama y tus primeras notas","it":"Il pentagramma e le tue prime note"}$cymbra$, 101, 2,
  $cymbra${"en":"The piano and middle C","fr":"Le piano et le do central","es":"El piano y el do central","it":"Il pianoforte e il do centrale"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u1-01-le-piano-et-le-do-central","instrument":"piano","track":"solfege","level":"beginner","title":{"en":"The piano and middle C","fr":"Le piano et le do central","es":"El piano y el do central","it":"Il pianoforte e il do centrale"},"summary":{"en":"Find your way around the keyboard and play middle C","fr":"Repère-toi sur le clavier et joue le do central","es":"Oriéntate en el teclado y toca el do central","it":"Orientati sulla tastiera e suona il do centrale"},"blocks":[{"type":"text","text":{"en":"Welcome! In ten seconds you will make your first sound: middle C.","fr":"Bienvenue ! Dans dix secondes, tu fais ton premier son : le do central.","es":"¡Hola! En diez segundos harás tu primer sonido: el do central.","it":"Ciao! Tra dieci secondi farai il tuo primo suono: il do centrale."}},{"type":"playKey","notes":[60],"prompt":{"en":"Play middle C: the white key just left of the two black keys, nearest the middle of the keyboard.","fr":"Joue le do central : la touche blanche juste à gauche des deux touches noires, la plus proche du milieu du clavier.","es":"Toca el do central: la tecla blanca justo a la izquierda de las dos teclas negras, la más cercana al centro del teclado.","it":"Suona il do centrale: il tasto bianco subito a sinistra dei due tasti neri, il più vicino al centro della tastiera."}},{"type":"question","prompt":{"en":"Look at the keyboard: how are the black keys grouped?","fr":"Regarde le clavier : comment les touches noires sont-elles regroupées ?","es":"Mira el teclado: ¿cómo se agrupan las teclas negras?","it":"Guarda la tastiera: come sono raggruppati i tasti neri?"},"options":[{"en":"In twos and threes","fr":"Par deux et par trois","es":"De dos en dos y de tres en tres","it":"A gruppi di due e di tre"},{"en":"Randomly","fr":"Au hasard","es":"Al azar","it":"A caso"},{"en":"In fours","fr":"Par quatre","es":"De cuatro en cuatro","it":"A gruppi di quattro"}],"answerIndex":0,"feedback":{"en":"Yes — twos and threes, all along the keyboard. That pattern is your map: C always sits left of a group of two.","fr":"Oui — par deux et par trois, tout le long du clavier. Ce motif est ta boussole : do est toujours à gauche d'un groupe de deux.","es":"Sí: de dos en dos y de tres en tres, a lo largo de todo el teclado. Ese patrón es tu mapa: do siempre está a la izquierda de un grupo de dos.","it":"Sì: a gruppi di due e di tre, lungo tutta la tastiera. Quel disegno è la tua mappa: il do è sempre a sinistra di un gruppo di due."},"keyboard":true},{"type":"playKey","notes":[48,60,72],"prompt":{"en":"Every group of two black keys has a C on its left. Play three of them: low, middle, high.","fr":"Chaque groupe de deux touches noires a un do à sa gauche. Joues-en trois : grave, central, aigu.","es":"Cada grupo de dos teclas negras tiene un do a su izquierda. Toca tres: grave, central, agudo.","it":"Ogni gruppo di due tasti neri ha un do alla sua sinistra. Suonane tre: grave, centrale, acuto."}},{"type":"earChoice","notes":["C3","C5"],"answerId":"up","choices":[{"id":"up","label":{"en":"Higher","fr":"Plus aiguë","es":"Más aguda","it":"Più acuta"}},{"id":"down","label":{"en":"Lower","fr":"Plus grave","es":"Más grave","it":"Più grave"}}],"prompt":{"en":"Listen to two Cs: is the second note higher or lower?","fr":"Écoute deux do : la deuxième note est-elle plus aiguë ou plus grave ?","es":"Escucha dos do: ¿la segunda nota es más aguda o más grave?","it":"Ascolta due do: la seconda nota è più acuta o più grave?"}},{"type":"earChoice","notes":["C5","C3"],"answerId":"down","choices":[{"id":"up","label":{"en":"Higher","fr":"Plus aiguë","es":"Más aguda","it":"Più acuta"}},{"id":"down","label":{"en":"Lower","fr":"Plus grave","es":"Más grave","it":"Più grave"}}],"prompt":{"en":"One more pair of Cs: is the second note higher or lower this time?","fr":"Encore une paire de do : cette fois, la deuxième note est-elle plus aiguë ou plus grave ?","es":"Otro par de do: esta vez, ¿la segunda nota es más aguda o más grave?","it":"Un'altra coppia di do: questa volta la seconda nota è più acuta o più grave?"}},{"type":"text","text":{"en":"Great start! You know the keyboard's map of twos and threes, and you can find every C — including middle C.","fr":"Beau départ ! Tu connais la carte du clavier par deux et par trois, et tu sais trouver tous les do — y compris le do central.","es":"¡Buen comienzo! Ya conoces el mapa del teclado en grupos de dos y de tres, y sabes encontrar todos los do, incluido el do central.","it":"Ottimo inizio! Conosci la mappa della tastiera a gruppi di due e di tre, e sai trovare tutti i do — compreso il do centrale."}}]}$cymbra$
),
(
  'sol-u1-02-la-portee', 'published', 'piano', 'solfege', 'beginner',
  'u1', $cymbra${"en":"The staff and your first notes","fr":"La portée et tes premières notes","es":"El pentagrama y tus primeras notas","it":"Il pentagramma e le tue prime note"}$cymbra$, 102, 2,
  $cymbra${"en":"The staff","fr":"La portée","es":"El pentagrama","it":"Il pentagramma"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u1-02-la-portee","instrument":"piano","track":"solfege","level":"beginner","title":{"en":"The staff","fr":"La portée","es":"El pentagrama","it":"Il pentagramma"},"summary":{"en":"Five lines, four spaces: where the notes live","fr":"Cinq lignes, quatre interlignes : la maison des notes","es":"Cinco líneas, cuatro espacios: la casa de las notas","it":"Cinque righe, quattro spazi: la casa delle note"},"blocks":[{"type":"text","text":{"en":"Music is written on a staff: five lines and four spaces. The higher a note sits on it, the higher it sounds.","fr":"La musique s'écrit sur une portée : cinq lignes et quatre interlignes. Plus une note est placée haut, plus elle sonne aigu.","es":"La música se escribe en un pentagrama: cinco líneas y cuatro espacios. Cuanto más arriba está una nota, más aguda suena.","it":"La musica si scrive sul pentagramma: cinque righe e quattro spazi. Più una nota è in alto, più suona acuta."}},{"type":"diagram","id":"staff-lines"},{"type":"staff","clef":"treble","elements":[{"p":"E4","fig":"quarter"},{"p":"G4","fig":"quarter"},{"p":"B4","fig":"quarter"}],"caption":{"en":"Three notes climbing: one on the first line, one on the second, one on the third.","fr":"Trois notes qui grimpent : une sur la première ligne, une sur la deuxième, une sur la troisième.","es":"Tres notas que suben: una en la primera línea, otra en la segunda y otra en la tercera.","it":"Tre note che salgono: una sulla prima riga, una sulla seconda, una sulla terza."}},{"type":"earChoice","notes":["E4","B4"],"answerId":"up","reveal":true,"choices":[{"id":"up","label":{"en":"Higher","fr":"Plus aiguë","es":"Más aguda","it":"Più acuta"}},{"id":"down","label":{"en":"Lower","fr":"Plus grave","es":"Más grave","it":"Più grave"}}],"prompt":{"en":"Listen to the first-line note, then the third-line note: is the second note higher or lower?","fr":"Écoute la note de la première ligne, puis celle de la troisième : la deuxième note est-elle plus aiguë ou plus grave ?","es":"Escucha la nota de la primera línea y luego la de la tercera: ¿la segunda nota es más aguda o más grave?","it":"Ascolta la nota della prima riga, poi quella della terza: la seconda nota è più acuta o più grave?"}},{"type":"placeNote","clef":"treble","targets":["E4","F4"],"prompt":{"en":"Place a note ON the bottom line, then IN the first space just above it.","fr":"Pose une note SUR la première ligne, puis DANS le premier interligne juste au-dessus.","es":"Coloca una nota SOBRE la primera línea y luego EN el primer espacio justo encima.","it":"Metti una nota SULLA prima riga, poi NEL primo spazio subito sopra."}},{"type":"question","prompt":{"en":"A note placed higher on the staff sounds…","fr":"Une note placée plus haut sur la portée sonne…","es":"Una nota colocada más arriba en el pentagrama suena…","it":"Una nota scritta più in alto sul pentagramma suona…"},"options":[{"en":"Higher","fr":"Plus aigu","es":"Más aguda","it":"Più acuta"},{"en":"Lower","fr":"Plus grave","es":"Más grave","it":"Più grave"}],"answerIndex":0,"feedback":{"en":"Exactly — height on the staff mirrors pitch: higher on the lines means higher in sound.","fr":"Exactement — la hauteur sur la portée suit le son : plus haut sur les lignes, plus aigu à l'oreille.","es":"Exacto: la altura en el pentagrama refleja el sonido; cuanto más arriba, más agudo.","it":"Esatto: l'altezza sul pentagramma rispecchia il suono; più in alto, più acuto."}},{"type":"earChoice","notes":["G4","E4"],"answerId":"down","choices":[{"id":"up","label":{"en":"Higher","fr":"Plus aiguë","es":"Más aguda","it":"Più acuta"}},{"id":"down","label":{"en":"Lower","fr":"Plus grave","es":"Más grave","it":"Più grave"}}],"prompt":{"en":"By ear now: a second-line note, then a bottom-line note. Is the second note higher or lower?","fr":"À l'oreille maintenant : une note sur la deuxième ligne, puis une sur la première. La deuxième note est-elle plus aiguë ou plus grave ?","es":"Ahora de oído: una nota en la segunda línea y luego una en la primera. ¿La segunda nota es más aguda o más grave?","it":"Ora a orecchio: una nota sulla seconda riga, poi una sulla prima. La seconda nota è più acuta o più grave?"}},{"type":"text","text":{"en":"You know the staff: five lines, four spaces, and higher on it means higher in sound. Next stop: the clef that names the notes.","fr":"Tu connais la portée : cinq lignes, quatre interlignes, et plus c'est haut, plus c'est aigu. Prochaine étape : la clé qui donne leur nom aux notes.","es":"Ya conoces el pentagrama: cinco líneas, cuatro espacios, y más arriba significa más agudo. Próxima parada: la clave que da nombre a las notas.","it":"Conosci il pentagramma: cinque righe, quattro spazi, e più in alto vuol dire più acuto. Prossima tappa: la chiave che dà il nome alle note."}}]}$cymbra$
),
(
  'sol-u1-03-la-cle-de-sol', 'published', 'piano', 'solfege', 'beginner',
  'u1', $cymbra${"en":"The staff and your first notes","fr":"La portée et tes premières notes","es":"El pentagrama y tus primeras notas","it":"Il pentagramma e le tue prime note"}$cymbra$, 103, 2,
  $cymbra${"en":"The treble clef","fr":"La clé de sol","es":"La clave de sol","it":"La chiave di violino"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u1-03-la-cle-de-sol","instrument":"piano","track":"solfege","level":"beginner","title":{"en":"The treble clef","fr":"La clé de sol","es":"La clave de sol","it":"La chiave di violino"},"summary":{"en":"The clef that names the G line","fr":"La clé qui nomme la ligne du sol","es":"La clave que da nombre a la línea del sol","it":"La chiave che dà il nome alla riga del sol"},"blocks":[{"type":"text","text":{"en":"A staff alone doesn't name its notes — a clef does. The treble clef curls around the second line and calls it G.","fr":"Une portée seule ne nomme pas ses notes — c'est le rôle de la clé. La clé de sol s'enroule autour de la deuxième ligne et la baptise sol.","es":"Un pentagrama solo no da nombre a sus notas: eso lo hace la clave. La clave de sol se enrosca en la segunda línea y la llama sol.","it":"Il pentagramma da solo non dà il nome alle note: ci pensa la chiave. La chiave di violino si avvolge attorno alla seconda riga e la chiama sol."}},{"type":"diagram","id":"treble-clef"},{"type":"staff","clef":"treble","labels":true,"elements":[{"p":"G4","fig":"quarter"}],"caption":{"en":"The note on the second line — the one the clef wraps — is G.","fr":"La note sur la deuxième ligne — celle que la clé entoure — est sol.","es":"La nota de la segunda línea, la que abraza la clave, es sol.","it":"La nota sulla seconda riga — quella avvolta dalla chiave — è sol."}},{"type":"readPlay","mode":"drill","clef":"treble","labels":"always","notes":["G4"],"prompt":{"en":"Play the note the clef points at — its name is written to help you.","fr":"Joue la note que la clé désigne — son nom est écrit pour t'aider.","es":"Toca la nota que señala la clave: su nombre está escrito para ayudarte.","it":"Suona la nota indicata dalla chiave: il suo nome è scritto per aiutarti."}},{"type":"placeNote","clef":"treble","targets":["G4"],"prompt":{"en":"Your turn: place a note on the clef's line, the second line.","fr":"À toi : pose une note sur la ligne de la clé, la deuxième ligne.","es":"Te toca: coloca una nota en la línea de la clave, la segunda línea.","it":"Tocca a te: metti una nota sulla riga della chiave, la seconda riga."}},{"type":"nameNote","clef":"treble","choiceCount":3,"notes":["G4"],"prompt":{"en":"The clef gives it away — what is this note called? Tap a name to hear it.","fr":"La clé te souffle la réponse — comment s'appelle cette note ? Touche un nom pour l'entendre.","es":"La clave te da la pista: ¿cómo se llama esta nota? Toca un nombre para oírla.","it":"La chiave ti dà l'indizio: come si chiama questa nota? Tocca un nome per sentirla."}},{"type":"question","prompt":{"en":"The treble clef curls around which line?","fr":"La clé de sol s'enroule autour de quelle ligne ?","es":"¿En qué línea se enrosca la clave de sol?","it":"Attorno a quale riga si avvolge la chiave di violino?"},"options":[{"en":"The second line, the G line","fr":"La deuxième ligne, celle du sol","es":"La segunda línea, la del sol","it":"La seconda riga, quella del sol"},{"en":"The bottom line","fr":"La première ligne","es":"La primera línea","it":"La prima riga"},{"en":"The top line","fr":"La cinquième ligne","es":"La quinta línea","it":"La quinta riga"}],"answerIndex":0,"feedback":{"en":"That's it — the clef anchors G on the second line, and every other note is counted from there.","fr":"C'est ça — la clé fixe le sol sur la deuxième ligne, et toutes les autres notes se comptent à partir de là.","es":"Eso es: la clave fija el sol en la segunda línea, y las demás notas se cuentan desde ahí.","it":"Proprio così: la chiave fissa il sol sulla seconda riga, e tutte le altre note si contano da lì."}},{"type":"text","text":{"en":"You've met the treble clef: it names the second line G, your anchor for reading. Soon you'll read notes all around it.","fr":"Tu as rencontré la clé de sol : elle nomme la deuxième ligne sol, ton point de repère pour lire. Bientôt, tu liras les notes tout autour.","es":"Ya conoces la clave de sol: nombra sol a la segunda línea, tu punto de referencia para leer. Pronto leerás las notas a su alrededor.","it":"Hai conosciuto la chiave di violino: chiama sol la seconda riga, il tuo punto di riferimento per leggere. Presto leggerai le note tutt'intorno."}}]}$cymbra$
),
(
  'sol-u1-04-do-re-mi', 'published', 'piano', 'solfege', 'beginner',
  'u1', $cymbra${"en":"The staff and your first notes","fr":"La portée et tes premières notes","es":"El pentagrama y tus primeras notas","it":"Il pentagramma e le tue prime note"}$cymbra$, 104, 2,
  $cymbra${"en":"C, D, E","fr":"Do, ré, mi","es":"Do, re, mi","it":"Do, re, mi"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u1-04-do-re-mi","instrument":"piano","track":"solfege","level":"beginner","title":{"en":"C, D, E","fr":"Do, ré, mi","es":"Do, re, mi","it":"Do, re, mi"},"summary":{"en":"Read and play C, D and E","fr":"Lire et jouer do, ré et mi","es":"Leer y tocar do, re y mi","it":"Leggere e suonare do, re e mi"},"blocks":[{"type":"text","text":{"en":"Three notes are enough for your first tunes: C, D and E. They live just above middle C.","fr":"Trois notes suffisent pour tes premières mélodies : do, ré et mi. Elles habitent juste au-dessus du do central.","es":"Con tres notas ya puedes tocar tus primeras melodías: do, re y mi. Viven justo encima del do central.","it":"Bastano tre note per le tue prime melodie: do, re e mi. Abitano appena sopra il do centrale."}},{"type":"staff","clef":"treble","labels":true,"elements":[{"p":"C4","fig":"quarter"},{"p":"D4","fig":"quarter"},{"p":"E4","fig":"quarter"}],"caption":{"en":"C sits on its little ledger line, D just under the bottom line, E on the bottom line.","fr":"Do se pose sur sa petite ligne, ré juste sous la première ligne, mi sur la première ligne.","es":"Do se apoya en su pequeña línea, re justo debajo de la primera línea, mi sobre la primera línea.","it":"Do sta sulla sua lineetta, re appena sotto la prima riga, mi sulla prima riga."}},{"type":"readPlay","mode":"drill","clef":"treble","labels":"afterMiss","notes":["C4","D4","E4"],"prompt":{"en":"Play the note shown on the staff.","fr":"Joue la note affichée sur la portée.","es":"Toca la nota que muestra el pentagrama.","it":"Suona la nota mostrata sul pentagramma."}},{"type":"nameNote","clef":"treble","choiceCount":3,"notes":["D4","C4","E4"],"prompt":{"en":"What is this note called? Tap a name to hear it.","fr":"Comment s'appelle cette note ? Touche un nom pour l'entendre.","es":"¿Cómo se llama esta nota? Toca un nombre para oírla.","it":"Come si chiama questa nota? Tocca un nome per sentirla."}},{"type":"earChoice","notes":["C4","E4"],"answerId":"up","choices":[{"id":"up","label":{"en":"Higher","fr":"Plus aiguë","es":"Más aguda","it":"Più acuta"}},{"id":"down","label":{"en":"Lower","fr":"Plus grave","es":"Más grave","it":"Più grave"}}],"prompt":{"en":"Listen: is the second note higher or lower?","fr":"Écoute : la deuxième note est-elle plus aiguë ou plus grave ?","es":"Escucha: ¿la segunda nota es más aguda o más grave?","it":"Ascolta: la seconda nota è più acuta o più grave?"}},{"type":"readPlay","mode":"melody","clef":"treble","labels":"never","notes":["C4","D4","E4","D4","C4"],"prompt":{"en":"Your first melody: play the notes left to right.","fr":"Ta première mélodie : joue les notes de gauche à droite.","es":"Tu primera melodía: toca las notas de izquierda a derecha.","it":"La tua prima melodia: suona le note da sinistra a destra."}},{"type":"text","text":{"en":"Well done! You now read C, D and E — and you just played your first melody.","fr":"Bravo ! Tu sais lire do, ré et mi — et tu viens de jouer ta première mélodie.","es":"¡Muy bien! Ya lees do, re y mi — y acabas de tocar tu primera melodía.","it":"Bravo! Ora leggi do, re e mi — e hai appena suonato la tua prima melodia."}}]}$cymbra$
),
