  $cymbra${"en":"Checkpoint: bass clef","fr":"Bilan : la clé de fa","es":"Repaso: la clave de fa","it":"Ripasso: la chiave di basso"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u4-06-bilan-cle-de-fa","instrument":"piano","track":"solfege","level":"intermediate","title":{"en":"Checkpoint: bass clef","fr":"Bilan : la clé de fa","es":"Repaso: la clave de fa","it":"Ripasso: la chiave di basso"},"summary":{"en":"Review the whole bass clef, lines to middle C","fr":"Réviser toute la clé de fa, des lignes au do central","es":"Repasar toda la clave de fa, de las líneas al do central","it":"Ripassare tutta la chiave di basso, dalle righe al do centrale"},"blocks":[{"type":"text","text":{"en":"Time to put the whole bass clef together: lines, spaces and middle C. Show what your left hand has learned.","fr":"L'heure est venue de rassembler toute la clé de fa : lignes, interlignes et do central. Montre ce que ta main gauche a appris.","es":"Es hora de reunir toda la clave de fa: líneas, espacios y do central. Enseña lo que ha aprendido tu mano izquierda.","it":"È ora di mettere insieme tutta la chiave di basso: righe, spazi e do centrale. Mostra cosa ha imparato la tua mano sinistra."}},{"type":"nameNote","clef":"bass","choiceCount":4,"notes":["F3","A3","C3","E3","G3"],"prompt":{"en":"Five notes from all over the bass staff — name each one. Tap a name to hear it.","fr":"Cinq notes venues de toute la portée de fa — nomme chacune d'elles. Touche un nom pour l'entendre.","es":"Cinco notas de toda la clave de fa — nombra cada una. Toca un nombre para oírla.","it":"Cinque note da tutta la chiave di basso — dai un nome a ciascuna. Tocca un nome per sentirla."}},{"type":"readPlay","mode":"melody","clef":"bass","labels":"never","notes":["C3","D3","E3","F3","G3","F3","E3","D3","C3"],"prompt":{"en":"A scale walk in the left hand: up from C to G, then back down.","fr":"Une gamme qui se promène à la main gauche : monte de do à sol, puis redescends.","es":"Un paseo de escala con la mano izquierda: sube de do a sol y vuelve a bajar.","it":"Una scala in passeggiata per la mano sinistra: sali da do a sol, poi ridiscendi."}},{"type":"placeNote","clef":"bass","targets":["A3"],"prompt":{"en":"Place A on the top line of the bass staff.","fr":"Pose le la sur la ligne la plus haute de la portée de fa.","es":"Coloca el la en la línea más alta de la clave de fa.","it":"Posiziona il la sulla riga più alta della chiave di basso."}},{"type":"earChoice","notes":["G2","G3"],"answerId":"up","choices":[{"id":"up","label":{"en":"Higher","fr":"Plus aiguë","es":"Más aguda","it":"Più acuta"}},{"id":"down","label":{"en":"Lower","fr":"Plus grave","es":"Más grave","it":"Più grave"}}],"prompt":{"en":"One last listen: two Gs an octave apart — is the second note higher or lower?","fr":"Une dernière écoute : deux sol à une octave d'écart — la deuxième note est-elle plus aiguë ou plus grave ?","es":"Una última escucha: dos sol a una octava de distancia — ¿la segunda nota es más aguda o más grave?","it":"Un ultimo ascolto: due sol a un'ottava di distanza — la seconda nota è più acuta o più grave?"}},{"type":"text","text":{"en":"Both clefs are yours now: treble, bass and the bridge between them, middle C. Your two hands can read together!","fr":"Les deux clés sont à toi : la clé de sol, la clé de fa et le pont qui les relie, le do central. Tes deux mains savent lire ensemble !","es":"Las dos claves ya son tuyas: la de sol, la de fa y el puente que las une, el do central. ¡Tus dos manos ya leen juntas!","it":"Le due chiavi sono tue: violino, basso e il ponte che le unisce, il do centrale. Le tue due mani ora leggono insieme!"}}]}$cymbra$
),
(
  'sol-u5-01-les-croches', 'published', 'piano', 'solfege', 'intermediate',
  'u5', $cymbra${"en":"Eighth notes and new meters","fr":"Croches et nouvelles mesures","es":"Corcheas y nuevos compases","it":"Crome e nuovi tempi"}$cymbra$, 501, 2,
  $cymbra${"en":"Eighth notes","fr":"Les croches","es":"Las corcheas","it":"Le crome"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u5-01-les-croches","instrument":"piano","track":"solfege","level":"intermediate","title":{"en":"Eighth notes","fr":"Les croches","es":"Las corcheas","it":"Le crome"},"summary":{"en":"Read and tap eighth notes: two per beat","fr":"Lire et taper les croches : deux par temps","es":"Leer y tocar las corcheas: dos por tiempo","it":"Leggere e battere le crome: due per movimento"},"blocks":[{"type":"text","text":{"en":"So far every note took at least one beat. Meet the eighth note: two of them share a single beat.","fr":"Jusqu'ici, chaque note durait au moins un temps. Voici la croche : elles se mettent à deux pour un seul temps.","es":"Hasta ahora cada nota duraba al menos un tiempo. Llega la corchea: dos de ellas comparten un solo tiempo.","it":"Finora ogni nota durava almeno un movimento. Ecco la croma: in due si dividono un solo movimento."}},{"type":"diagram","id":"note-eighth"},{"type":"staff","clef":"treble","time":{"beats":4,"beatType":4},"elements":[{"p":"C4","fig":"quarter"},{"p":"D4","fig":"eighth"},{"p":"E4","fig":"eighth"},{"p":"F4","fig":"quarter"},{"p":"G4","fig":"quarter"}],"caption":{"en":"D and E share beat two: two eighth notes, one beat.","fr":"Ré et mi se partagent le deuxième temps : deux croches pour un temps.","es":"Re y mi comparten el segundo tiempo: dos corcheas para un tiempo.","it":"Re e mi si dividono il secondo movimento: due crome per un movimento."}},{"type":"rhythmTap","pattern":[{"fig":"quarter"},{"fig":"eighth"},{"fig":"eighth"},{"fig":"quarter"},{"fig":"quarter"}],"beats":4,"beatType":4,"bpm":70,"prompt":{"en":"Tap and count 'ONE, two-and, three, four' — the two eighths share beat two.","fr":"Tape en comptant « UN, deux-et, trois, quatre » — les deux croches se partagent le deuxième temps.","es":"Toca contando 'UN, dos-y, tres, cuatro': las dos corcheas comparten el segundo tiempo.","it":"Batti contando 'UNO, due-e, tre, quattro': le due crome si dividono il secondo movimento."}},{"type":"question","prompt":{"en":"How many eighth notes fit in one beat (a quarter note)?","fr":"Combien de croches tiennent dans un temps (une noire) ?","es":"¿Cuántas corcheas caben en un tiempo (una negra)?","it":"Quante crome stanno in un movimento (una semiminima)?"},"options":[{"en":"Two","fr":"Deux","es":"Dos","it":"Due"},{"en":"Three","fr":"Trois","es":"Tres","it":"Tre"},{"en":"Four","fr":"Quatre","es":"Cuatro","it":"Quattro"}],"answerIndex":0,"feedback":{"en":"Two eighth notes share one beat: count 'one-and'.","fr":"Deux croches se partagent un temps : compte « un-et ».","es":"Dos corcheas comparten un tiempo: cuenta 'un-y'.","it":"Due crome si dividono un movimento: conta 'uno-e'."}},{"type":"rhythmTap","pattern":[{"fig":"eighth"},{"fig":"eighth"},{"fig":"eighth"},{"fig":"eighth"},{"fig":"quarter"},{"fig":"quarter"}],"beats":4,"beatType":4,"bpm":70,"prompt":{"en":"Now two pairs: 'one-and, two-and, three, four'. Keep the eighths perfectly even.","fr":"Maintenant deux paires : « un-et, deux-et, trois, quatre ». Garde les croches bien régulières.","es":"Ahora dos parejas: 'un-y, dos-y, tres, cuatro'. Mantén las corcheas bien parejas.","it":"Ora due coppie: 'uno-e, due-e, tre, quattro'. Tieni le crome ben regolari."}},{"type":"rhythmTap","pattern":[{"fig":"eighth"},{"fig":"eighth"},{"fig":"quarter"},{"fig":"eighth"},{"fig":"eighth"},{"fig":"quarter"}],"beats":4,"beatType":4,"bpm":70,"prompt":{"en":"Last mix: 'one-and, two, three-and, four' — eighths and quarters take turns.","fr":"Dernier mélange : « un-et, deux, trois-et, quatre » — croches et noires alternent.","es":"Última mezcla: 'un-y, dos, tres-y, cuatro': corcheas y negras se alternan.","it":"Ultimo mix: 'uno-e, due, tre-e, quattro': crome e semiminime si alternano."}},{"type":"text","text":{"en":"You can now split the beat in two: eighth notes, counted 'one-and'. Your rhythms just got twice as lively.","fr":"Tu sais maintenant couper le temps en deux : les croches, comptées « un-et ». Tes rythmes viennent de gagner en vivacité.","es":"Ya sabes partir el tiempo en dos: las corcheas, contadas 'un-y'. Tus ritmos acaban de ganar chispa.","it":"Ora sai dividere il movimento in due: le crome, contate 'uno-e'. I tuoi ritmi sono appena diventati più vivaci."}}]}$cymbra$
),
