  'u5', $cymbra${"en":"Eighth notes and new meters","fr":"Croches et nouvelles mesures","es":"Corcheas y nuevos compases","it":"Crome e nuovi tempi"}$cymbra$, 502, 2,
  $cymbra${"en":"The dotted quarter","fr":"La noire pointée","es":"La negra con puntillo","it":"La semiminima col punto"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u5-02-la-noire-pointee","instrument":"piano","track":"solfege","level":"intermediate","title":{"en":"The dotted quarter","fr":"La noire pointée","es":"La negra con puntillo","it":"La semiminima col punto"},"summary":{"en":"Feel the dotted quarter: a beat and a half","fr":"Sentir la noire pointée : un temps et demi","es":"Sentir la negra con puntillo: un tiempo y medio","it":"Sentire la semiminima col punto: un movimento e mezzo"},"blocks":[{"type":"text","text":{"en":"A small dot after a note stretches it by half its value. The dotted quarter is the heartbeat of countless melodies.","fr":"Un petit point après une note l'allonge de la moitié de sa valeur. La noire pointée est le cœur de mille mélodies.","es":"Un puntito tras una nota la alarga la mitad de su valor. La negra con puntillo late en mil melodías.","it":"Un puntino dopo una nota la allunga della metà del suo valore. La semiminima col punto batte in mille melodie."}},{"type":"staff","clef":"treble","time":{"beats":4,"beatType":4},"elements":[{"p":"C4","fig":"quarter","dots":1},{"p":"D4","fig":"eighth"},{"p":"E4","fig":"half"}],"caption":{"en":"The dot stretches C to a beat and a half — D slips in on the 'and' of two.","fr":"Le point étire do sur un temps et demi — ré se glisse sur le « et » du deuxième temps.","es":"El puntillo alarga el do a un tiempo y medio: re se cuela en el 'y' del segundo tiempo.","it":"Il punto allunga il do a un movimento e mezzo: re entra sul 'e' del secondo movimento."}},{"type":"rhythmTap","pattern":[{"fig":"quarter","dots":1},{"fig":"eighth"},{"fig":"quarter"},{"fig":"quarter"}],"beats":4,"beatType":4,"bpm":60,"prompt":{"en":"Tap on 'ONE', then wait — the next tap falls on the 'and' of two.","fr":"Tape sur « UN », puis attends — le tap suivant tombe sur le « et » du deuxième temps.","es":"Toca en 'UN' y espera: el siguiente toque cae en el 'y' del segundo tiempo.","it":"Batti su 'UNO' e aspetta: il colpo successivo cade sul 'e' del secondo movimento."}},{"type":"question","prompt":{"en":"How long does a dotted quarter last?","fr":"Combien de temps dure une noire pointée ?","es":"¿Cuánto dura una negra con puntillo?","it":"Quanto dura una semiminima col punto?"},"options":[{"en":"A beat and a half","fr":"Un temps et demi","es":"Un tiempo y medio","it":"Un movimento e mezzo"},{"en":"Two beats","fr":"Deux temps","es":"Dos tiempos","it":"Due movimenti"}],"answerIndex":0,"feedback":{"en":"The dot adds half the value: one beat plus a half makes a beat and a half.","fr":"Le point ajoute la moitié de la valeur : un temps plus une moitié, cela fait un temps et demi.","es":"El puntillo añade la mitad del valor: un tiempo más medio hacen un tiempo y medio.","it":"Il punto aggiunge metà del valore: un movimento più mezzo fa un movimento e mezzo."}},{"type":"rhythmTap","pattern":[{"fig":"quarter","dots":1},{"fig":"eighth"},{"fig":"half"}],"beats":4,"beatType":4,"bpm":60,"prompt":{"en":"Same start, calm ending: 'ONE … and-of-two … THREE', and let the half note ring.","fr":"Même départ, fin posée : « UN … et-de-deux … TROIS », et laisse sonner la blanche.","es":"Mismo comienzo, final tranquilo: 'UN… y-de-dos… TRES', y deja sonar la blanca.","it":"Stesso inizio, finale calmo: 'UNO… e-di-due… TRE', e lascia suonare la minima."}},{"type":"rhythmTap","pattern":[{"fig":"quarter"},{"fig":"quarter","dots":1},{"fig":"eighth"},{"fig":"quarter"}],"beats":4,"beatType":4,"bpm":60,"prompt":{"en":"The dotted figure moved to the middle of the bar — listen for 'one, TWO … and-of-three, four'.","fr":"La figure pointée s'est déplacée au milieu de la mesure — guette « un, DEUX … et-de-trois, quatre ».","es":"La figura con puntillo se movió al centro del compás: busca 'un, DOS… y-de-tres, cuatro'.","it":"La figura col punto si è spostata al centro della battuta: cerca 'uno, DUE… e-di-tre, quattro'."}},{"type":"text","text":{"en":"The dot adds half the value: a dotted quarter lasts a beat and a half. You tapped it — now you'll recognize it everywhere.","fr":"Le point ajoute la moitié de la valeur : une noire pointée dure un temps et demi. Tu l'as tapée — tu la reconnaîtras partout.","es":"El puntillo añade la mitad del valor: una negra con puntillo dura un tiempo y medio. La tocaste, y ahora la reconocerás en todas partes.","it":"Il punto aggiunge metà del valore: una semiminima col punto dura un movimento e mezzo. L'hai battuta — ora la riconoscerai ovunque."}}]}$cymbra$
),
(
  'sol-u5-03-la-blanche-pointee-et-la-valse', 'published', 'piano', 'solfege', 'intermediate',
  'u5', $cymbra${"en":"Eighth notes and new meters","fr":"Croches et nouvelles mesures","es":"Corcheas y nuevos compases","it":"Crome e nuovi tempi"}$cymbra$, 503, 2,
  $cymbra${"en":"The dotted half and the waltz","fr":"La blanche pointée et la valse","es":"La blanca con puntillo y el vals","it":"La minima col punto e il valzer"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u5-03-la-blanche-pointee-et-la-valse","instrument":"piano","track":"solfege","level":"intermediate","title":{"en":"The dotted half and the waltz","fr":"La blanche pointée et la valse","es":"La blanca con puntillo y el vals","it":"La minima col punto e il valzer"},"summary":{"en":"The dotted half: one note, one waltz bar","fr":"La blanche pointée : une note, une mesure de valse","es":"La blanca con puntillo: una nota, un compás de vals","it":"La minima col punto: una nota, una battuta di valzer"},"blocks":[{"type":"text","text":{"en":"Put a dot on a half note and it lasts three beats — exactly one bar of 3/4. Welcome to the waltz.","fr":"Ajoute un point à une blanche et elle dure trois temps — exactement une mesure à 3/4. Bienvenue dans la valse.","es":"Ponle un puntillo a una blanca y dura tres tiempos: justo un compás de 3/4. El vals te espera.","it":"Metti un punto a una minima e dura tre movimenti: esattamente una battuta in 3/4. Il valzer ti aspetta."}},{"type":"staff","clef":"treble","time":{"beats":3,"beatType":4},"elements":[{"p":"G4","fig":"half","dots":1}],"caption":{"en":"One dotted half fills the whole 3/4 bar — one note, one waltz bar.","fr":"Une blanche pointée remplit toute la mesure à 3/4 — une note, une mesure de valse.","es":"Una blanca con puntillo llena todo el compás de 3/4: una nota, un compás de vals.","it":"Una minima col punto riempie l'intera battuta in 3/4: una nota, una battuta di valzer."}},{"type":"rhythmTap","pattern":[{"fig":"half","dots":1}],"beats":3,"beatType":4,"bpm":60,"passRatio":1.0,"prompt":{"en":"One single tap on 'ONE', then let it fill all three beats of the bar.","fr":"Un seul tap sur « UN », puis laisse-le remplir les trois temps de la mesure.","es":"Un solo toque en 'UN', y deja que llene los tres tiempos del compás.","it":"Un solo colpo su 'UNO', e lascialo riempire i tre movimenti della battuta."}},{"type":"rhythmTap","pattern":[{"fig":"quarter"},{"fig":"quarter"},{"fig":"quarter"},{"fig":"half","dots":1}],"beats":3,"beatType":4,"bpm":70,"prompt":{"en":"A waltz step: 'one, two, three', then one long note for the whole next bar.","fr":"Un pas de valse : « un, deux, trois », puis une seule note longue pour toute la mesure suivante.","es":"Un paso de vals: 'un, dos, tres', y luego una sola nota larga para todo el compás siguiente.","it":"Un passo di valzer: 'uno, due, tre', poi una sola nota lunga per tutta la battuta successiva."}},{"type":"question","prompt":{"en":"In 3/4, how much of the bar does the dotted half fill?","fr":"En 3/4, quelle part de la mesure la blanche pointée remplit-elle ?","es":"En 3/4, ¿cuánto del compás llena la blanca con puntillo?","it":"In 3/4, quanta parte della battuta riempie la minima col punto?"},"options":[{"en":"The whole bar — three beats","fr":"Toute la mesure — trois temps","es":"Todo el compás: tres tiempos","it":"Tutta la battuta: tre movimenti"},{"en":"Only the first two beats","fr":"Seulement les deux premiers temps","es":"Solo los dos primeros tiempos","it":"Solo i primi due movimenti"}],"answerIndex":0,"feedback":{"en":"Two beats plus one from the dot: three — the whole waltz bar.","fr":"Deux temps plus un grâce au point : trois — toute la mesure de valse.","es":"Dos tiempos más uno del puntillo: tres, el compás de vals entero.","it":"Due movimenti più uno dal punto: tre, l'intera battuta di valzer."}},{"type":"rhythmTap","pattern":[{"fig":"half","dots":1},{"fig":"quarter"},{"fig":"quarter"},{"fig":"quarter"}],"beats":3,"beatType":4,"bpm":70,"prompt":{"en":"Now the long note comes first: hold through the bar, then answer 'one, two, three'.","fr":"Cette fois la note longue vient d'abord : laisse passer la mesure, puis réponds « un, deux, trois ».","es":"Ahora la nota larga va primero: deja pasar el compás y responde 'un, dos, tres'.","it":"Ora la nota lunga viene prima: lascia passare la battuta, poi rispondi 'uno, due, tre'."}},{"type":"text","text":{"en":"Dotted half note: two beats plus one, a whole waltz bar in a single note. Keep that gentle one-two-three going.","fr":"La blanche pointée : deux temps plus un, toute une mesure de valse en une seule note. Garde ce doux « un-deux-trois » en tête.","es":"La blanca con puntillo: dos tiempos más uno, todo un compás de vals en una sola nota. Guarda ese suave 'un-dos-tres'.","it":"La minima col punto: due movimenti più uno, un'intera battuta di valzer in una sola nota. Tieni con te quel dolce 'uno-due-tre'."}}]}$cymbra$
),
(
  'sol-u5-04-le-6-8', 'published', 'piano', 'solfege', 'intermediate',
  'u5', $cymbra${"en":"Eighth notes and new meters","fr":"Croches et nouvelles mesures","es":"Corcheas y nuevos compases","it":"Crome e nuovi tempi"}$cymbra$, 504, 2,
  $cymbra${"en":"6/8, the swaying meter","fr":"Le 6/8, la mesure qui balance","es":"El 6/8, el compás que se mece","it":"Il 6/8, il tempo che dondola"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u5-04-le-6-8","instrument":"piano","track":"solfege","level":"intermediate","title":{"en":"6/8, the swaying meter","fr":"Le 6/8, la mesure qui balance","es":"El 6/8, el compás que se mece","it":"Il 6/8, il tempo che dondola"},"summary":{"en":"Feel 6/8 in six steps and two big beats","fr":"Sentir le 6/8 en six pas et deux grands temps","es":"Sentir el 6/8 en seis pasos y dos tiempos grandes","it":"Sentire il 6/8 in sei passi e due grandi movimenti"},"blocks":[{"type":"text","text":{"en":"6/8 counts six quick eighths per bar, but it flows in two big swaying beats. It's the meter of barcarolles and lullabies.","fr":"Le 6/8 compte six croches rapides par mesure, mais il coule en deux grands temps qui balancent. C'est la mesure des barcarolles et des berceuses.","es":"El 6/8 cuenta seis corcheas rápidas por compás, pero fluye en dos tiempos grandes que se mecen. Es el compás de las barcarolas y las canciones de cuna.","it":"Il 6/8 conta sei crome veloci per battuta, ma scorre in due grandi movimenti che dondolano. È il tempo delle barcarole e delle ninne nanne."}},{"type":"staff","clef":"treble","time":{"beats":6,"beatType":8},"elements":[{"p":"C4","fig":"eighth"},{"p":"D4","fig":"eighth"},{"p":"E4","fig":"eighth"},{"p":"F4","fig":"eighth"},{"p":"G4","fig":"eighth"},{"p":"F4","fig":"eighth"}],"caption":{"en":"Six light steps up and back — two groups of three eighth notes.","fr":"Six petits pas qui montent et reviennent — deux groupes de trois croches.","es":"Seis pasitos que suben y vuelven: dos grupos de tres corcheas.","it":"Sei piccoli passi che salgono e tornano: due gruppi di tre crome."}},{"type":"rhythmTap","pattern":[{"fig":"eighth"},{"fig":"eighth"},{"fig":"eighth"},{"fig":"eighth"},{"fig":"eighth"},{"fig":"eighth"}],"beats":6,"beatType":8,"bpm":100,"prompt":{"en":"Tap the six light steps: 'one-two-three, four-five-six', leaning gently on one and four.","fr":"Tape les six petits pas : « un-deux-trois, quatre-cinq-six », en appuyant doucement sur un et quatre.","es":"Toca los seis pasitos: 'un-dos-tres, cuatro-cinco-seis', apoyándote suavemente en el uno y el cuatro.","it":"Batti i sei piccoli passi: 'uno-due-tre, quattro-cinque-sei', appoggiandoti dolcemente su uno e quattro."}},{"type":"rhythmTap","pattern":[{"fig":"quarter","dots":1},{"fig":"quarter","dots":1}],"beats":6,"beatType":8,"bpm":90,"prompt":{"en":"Now feel it in TWO big beats: tap only on 'ONE' and 'FOUR' and let each one sway.","fr":"Maintenant sens-le en DEUX grands temps : tape seulement sur « UN » et « QUATRE » et laisse balancer.","es":"Ahora siéntelo en DOS tiempos grandes: toca solo en 'UN' y 'CUATRO' y déjalo mecerse.","it":"Ora sentilo in DUE grandi movimenti: batti solo su 'UNO' e 'QUATTRO' e lascialo dondolare."}},{"type":"question","prompt":{"en":"How do you feel 6/8 when it flows?","fr":"Comment sens-tu le 6/8 quand il coule ?","es":"¿Cómo sientes el 6/8 cuando fluye?","it":"Come senti il 6/8 quando scorre?"},"options":[{"en":"In two big swaying beats","fr":"En deux grands temps qui balancent","es":"En dos tiempos grandes que se mecen","it":"In due grandi movimenti che dondolano"},{"en":"In six separate little beats","fr":"En six petits temps séparés","es":"En seis tiempos pequeños separados","it":"In sei piccoli movimenti separati"}],"answerIndex":0,"feedback":{"en":"Both are real — but the sway comes from the two big beats, three eighths each.","fr":"Les deux existent — mais le balancement vient des deux grands temps, trois croches chacun.","es":"Las dos cosas son ciertas, pero el vaivén nace de los dos tiempos grandes, tres corcheas cada uno.","it":"Sono vere entrambe — ma il dondolio nasce dai due grandi movimenti, tre crome ciascuno."}},{"type":"rhythmTap","pattern":[{"fig":"eighth"},{"fig":"eighth"},{"fig":"eighth"},{"fig":"quarter","dots":1}],"beats":6,"beatType":8,"bpm":90,"prompt":{"en":"Half and half: three little steps, then one big swing — 'one-two-three, FOUR…'.","fr":"Moitié-moitié : trois petits pas, puis un grand balancement — « un-deux-trois, QUATRE… ».","es":"Mitad y mitad: tres pasitos y luego un gran balanceo: 'un-dos-tres, CUATRO…'.","it":"Metà e metà: tre piccoli passi, poi un grande slancio: 'uno-due-tre, QUATTRO…'."}},{"type":"text","text":{"en":"6/8: six eighth notes on paper, two big beats in your body. When it sways, you're doing it right.","fr":"Le 6/8 : six croches sur le papier, deux grands temps dans le corps. Quand ça balance, c'est que tu le joues bien.","es":"El 6/8: seis corcheas en el papel, dos tiempos grandes en el cuerpo. Cuando se mece, lo estás haciendo bien.","it":"Il 6/8: sei crome sulla carta, due grandi movimenti nel corpo. Quando dondola, lo stai suonando bene."}}]}$cymbra$
),
(
  'sol-u5-05-le-contretemps', 'published', 'piano', 'solfege', 'intermediate',
  'u5', $cymbra${"en":"Eighth notes and new meters","fr":"Croches et nouvelles mesures","es":"Corcheas y nuevos compases","it":"Crome e nuovi tempi"}$cymbra$, 505, 2,
  $cymbra${"en":"Offbeats","fr":"Le contretemps","es":"El contratiempo","it":"Il controtempo"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u5-05-le-contretemps","instrument":"piano","track":"solfege","level":"intermediate","title":{"en":"Offbeats","fr":"Le contretemps","es":"El contratiempo","it":"Il controtempo"},"summary":{"en":"Tap offbeats: rests on the beat, notes on the 'and'","fr":"Taper le contretemps : silences sur le temps, notes sur le « et »","es":"Tocar el contratiempo: silencios en el tiempo, notas en el 'y'","it":"Battere il controtempo: pause sul movimento, note sul 'e'"},"blocks":[{"type":"text","text":{"en":"Sometimes the music breathes on the beat and answers just after it. That answer on the 'and' is the offbeat.","fr":"Parfois la musique respire sur le temps et répond juste après. Cette réponse sur le « et », c'est le contretemps.","es":"A veces la música respira en el tiempo y responde justo después. Esa respuesta en el 'y' es el contratiempo.","it":"A volte la musica respira sul movimento e risponde subito dopo. Quella risposta sul 'e' è il controtempo."}},{"type":"staff","clef":"treble","time":{"beats":4,"beatType":4},"elements":[{"rest":true,"fig":"eighth"},{"p":"C4","fig":"eighth"},{"rest":true,"fig":"eighth"},{"p":"E4","fig":"eighth"},{"p":"G4","fig":"quarter"},{"p":"E4","fig":"quarter"}],"caption":{"en":"The eighth rests sit on beats one and two — the notes answer just after, on the 'and'.","fr":"Les demi-soupirs tombent sur les temps un et deux — les notes répondent juste après, sur le « et ».","es":"Los silencios de corchea caen en los tiempos uno y dos: las notas responden justo después, en el 'y'.","it":"Le pause di croma cadono sui movimenti uno e due: le note rispondono subito dopo, sul 'e'."}},{"type":"rhythmTap","pattern":[{"rest":true,"fig":"eighth"},{"fig":"eighth"},{"rest":true,"fig":"eighth"},{"fig":"eighth"},{"fig":"quarter"},{"fig":"quarter"}],"beats":4,"beatType":4,"bpm":60,"prompt":{"en":"Tap BETWEEN the clicks: the rest takes each beat, you answer on the 'and'.","fr":"Tape ENTRE les clics : le silence prend le temps, toi tu réponds sur le « et ».","es":"Toca ENTRE los clics: el silencio ocupa el tiempo y tú respondes en el 'y'.","it":"Batti TRA i clic: la pausa occupa il movimento, tu rispondi sul 'e'."}},{"type":"question","prompt":{"en":"In an offbeat pattern, where do your notes land?","fr":"Dans un contretemps, où tombent tes notes ?","es":"En un contratiempo, ¿dónde caen tus notas?","it":"In un controtempo, dove cadono le tue note?"},"options":[{"en":"Just after the beat, on the 'and'","fr":"Juste après le temps, sur le « et »","es":"Justo después del tiempo, en el 'y'","it":"Subito dopo il movimento, sul 'e'"},{"en":"Right on the beat","fr":"Pile sur le temps","es":"Justo en el tiempo","it":"Esattamente sul movimento"}],"answerIndex":0,"feedback":{"en":"The rest takes the beat — your note answers on the 'and'.","fr":"Le silence prend le temps — ta note répond sur le « et ».","es":"El silencio ocupa el tiempo: tu nota responde en el 'y'.","it":"La pausa occupa il movimento: la tua nota risponde sul 'e'."}},{"type":"rhythmTap","pattern":[{"fig":"quarter"},{"rest":true,"fig":"eighth"},{"fig":"eighth"},{"fig":"half"}],"beats":4,"beatType":4,"bpm":60,"prompt":{"en":"Start on the beat this time: 'ONE', slip onto 'and-of-two', then land on the long 'THREE'.","fr":"Cette fois pars sur le temps : « UN », glisse sur « et-de-deux », puis pose-toi sur le long « TROIS ».","es":"Esta vez empieza en el tiempo: 'UN', salta al 'y-de-dos' y aterriza en el 'TRES' largo.","it":"Questa volta parti sul movimento: 'UNO', scivola su 'e-di-due', poi posati sul lungo 'TRE'."}},{"type":"rhythmTap","pattern":[{"rest":true,"fig":"eighth"},{"fig":"eighth"},{"rest":true,"fig":"eighth"},{"fig":"eighth"},{"rest":true,"fig":"eighth"},{"fig":"eighth"},{"rest":true,"fig":"eighth"},{"fig":"eighth"}],"beats":4,"beatType":4,"bpm":60,"prompt":{"en":"The full offbeat groove: four answers in a row, always just after the click.","fr":"Le contretemps complet : quatre réponses d'affilée, toujours juste après le clic.","es":"El contratiempo completo: cuatro respuestas seguidas, siempre justo después del clic.","it":"Il controtempo completo: quattro risposte di fila, sempre subito dopo il clic."}},{"type":"text","text":{"en":"Offbeats: the rest takes the beat, your note answers on the 'and'. That little push drives dance music everywhere.","fr":"Le contretemps : le silence prend le temps, ta note répond sur le « et ». Ce petit élan fait danser des musiques du monde entier.","es":"El contratiempo: el silencio ocupa el tiempo y tu nota responde en el 'y'. Ese pequeño impulso hace bailar músicas de todo el mundo.","it":"Il controtempo: la pausa occupa il movimento, la tua nota risponde sul 'e'. Quella piccola spinta fa ballare musiche di tutto il mondo."}}]}$cymbra$
),
(
  'sol-u5-06-bilan-rythme-2', 'published', 'piano', 'solfege', 'intermediate',
  'u5', $cymbra${"en":"Eighth notes and new meters","fr":"Croches et nouvelles mesures","es":"Corcheas y nuevos compases","it":"Crome e nuovi tempi"}$cymbra$, 506, 2,
  $cymbra${"en":"Checkpoint: rhythm II","fr":"Bilan : rythme, niveau 2","es":"Repaso: ritmo II","it":"Ripasso: ritmo II"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u5-06-bilan-rythme-2","instrument":"piano","track":"solfege","level":"intermediate","title":{"en":"Checkpoint: rhythm II","fr":"Bilan : rythme, niveau 2","es":"Repaso: ritmo II","it":"Ripasso: ritmo II"},"summary":{"en":"Checkpoint: all the unit's rhythms","fr":"Bilan : tous les rythmes de l'unité","es":"Repaso: todos los ritmos de la unidad","it":"Ripasso: tutti i ritmi dell'unità"},"blocks":[{"type":"text","text":{"en":"Time to put unit five together: eighths, dots, 3/4, 6/8 and offbeats. Three rhythms, one question — you have everything you need.","fr":"L'heure de rassembler l'unité cinq : croches, points, 3/4, 6/8 et contretemps. Trois rythmes, une question — tu as tout en main.","es":"Es hora de reunir la unidad cinco: corcheas, puntillos, 3/4, 6/8 y contratiempos. Tres ritmos, una pregunta: lo tienes todo a mano.","it":"È ora di mettere insieme l'unità cinque: crome, punti, 3/4, 6/8 e controtempi. Tre ritmi, una domanda: hai tutto in mano."}},{"type":"rhythmTap","pattern":[{"fig":"quarter","dots":1},{"fig":"eighth"},{"fig":"quarter"},{"fig":"eighth"},{"fig":"eighth"}],"beats":4,"beatType":4,"bpm":70,"prompt":{"en":"First figure check: 'ONE … and-of-two, three, four-and'.","fr":"Premier contrôle : « UN … et-de-deux, trois, quatre-et ».","es":"Primera prueba: 'UN… y-de-dos, tres, cuatro-y'.","it":"Prima verifica: 'UNO… e-di-due, tre, quattro-e'."}},{"type":"rhythmTap","pattern":[{"fig":"quarter"},{"fig":"eighth"},{"fig":"eighth"},{"fig":"quarter"}],"beats":3,"beatType":4,"bpm":70,"prompt":{"en":"Back to the waltz bar: 'one, two-and, three'.","fr":"Retour à la mesure de valse : « un, deux-et, trois ».","es":"De vuelta al compás de vals: 'un, dos-y, tres'.","it":"Di nuovo nella battuta di valzer: 'uno, due-e, tre'."}},{"type":"question","prompt":{"en":"What does a dot after a note do?","fr":"Que fait un point placé après une note ?","es":"¿Qué hace un puntillo después de una nota?","it":"Cosa fa un punto dopo una nota?"},"options":[{"en":"It adds half the note's value","fr":"Il ajoute la moitié de la valeur de la note","es":"Añade la mitad del valor de la nota","it":"Aggiunge metà del valore della nota"},{"en":"It doubles the note's value","fr":"Il double la valeur de la note","es":"Duplica el valor de la nota","it":"Raddoppia il valore della nota"}],"answerIndex":0,"feedback":{"en":"Half again: a dotted quarter is a quarter plus an eighth.","fr":"La moitié en plus : une noire pointée vaut une noire plus une croche.","es":"La mitad más: una negra con puntillo vale una negra más una corchea.","it":"Metà in più: una semiminima col punto vale una semiminima più una croma."}},{"type":"rhythmTap","pattern":[{"fig":"quarter","dots":1},{"fig":"eighth"},{"fig":"eighth"},{"fig":"eighth"}],"beats":6,"beatType":8,"bpm":90,"prompt":{"en":"And the 6/8 swing: one big 'ONE…', then 'four-five-six' to finish.","fr":"Et le balancement du 6/8 : un grand « UN… », puis « quatre-cinq-six » pour finir.","es":"Y el vaivén del 6/8: un gran 'UN…', y luego 'cuatro-cinco-seis' para terminar.","it":"E il dondolio del 6/8: un grande 'UNO…', poi 'quattro-cinque-sei' per finire."}},{"type":"text","text":{"en":"Rhythm level two, complete: your hands now know eighths, dotted notes, the waltz, 6/8 and the offbeat. From here on you don't count these figures — you feel them.","fr":"Rythme niveau deux, terminé : tes mains connaissent les croches, les notes pointées, la valse, le 6/8 et le contretemps. Désormais tu ne comptes plus ces figures — tu les sens.","es":"Ritmo nivel dos, completado: tus manos ya conocen las corcheas, los puntillos, el vals, el 6/8 y el contratiempo. A partir de ahora no cuentas estas figuras: las sientes.","it":"Ritmo livello due, completato: le tue mani ora conoscono le crome, i punti, il valzer, il 6/8 e il controtempo. D'ora in poi non conti più queste figure: le senti."}}]}$cymbra$
),
(
  'sol-u6-01-ton-et-demi-ton', 'published', 'piano', 'solfege', 'intermediate',
  'u6', $cymbra${"en":"Sharps, flats and keys","fr":"Dièses, bémols et tonalités","es":"Sostenidos, bemoles y tonalidades","it":"Diesis, bemolli e tonalità"}$cymbra$, 601, 2,
  $cymbra${"en":"Whole and half steps","fr":"Ton et demi-ton","es":"Tono y semitono","it":"Tono e semitono"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u6-01-ton-et-demi-ton","instrument":"piano","track":"solfege","level":"intermediate","title":{"en":"Whole and half steps","fr":"Ton et demi-ton","es":"Tono y semitono","it":"Tono e semitono"},"summary":{"en":"Hear and name whole and half steps","fr":"Entendre et nommer les tons et les demi-tons","es":"Escuchar y nombrar tonos y semitonos","it":"Ascoltare e nominare toni e semitoni"},"blocks":[{"type":"text","text":{"en":"A half step is the smallest distance on the piano: from one key to its nearest neighbor. Two half steps make a whole step.","fr":"Le demi-ton est la plus petite distance du piano : d'une touche à sa voisine immédiate. Deux demi-tons font un ton.","es":"El semitono es la distancia más pequeña del piano: de una tecla a su vecina inmediata. Dos semitonos forman un tono.","it":"Il semitono è la distanza più piccola del pianoforte: da un tasto al suo vicino immediato. Due semitoni formano un tono."}},{"type":"readPlay","mode":"drill","clef":"treble","labels":"always","notes":["E4","F4"],"prompt":{"en":"Play the note shown: E and F are direct neighbors — no black key between them.","fr":"Joue la note affichée : mi et fa sont voisins directs — aucune touche noire entre eux.","es":"Toca la nota que se muestra: mi y fa son vecinos directos — sin tecla negra entre ellos.","it":"Suona la nota mostrata: mi e fa sono vicini diretti — nessun tasto nero tra loro."}},{"type":"earChoice","notes":["C4","C#4"],"answerId":"half","choices":[{"id":"half","label":{"en":"A half step","fr":"Un demi-ton","es":"Un semitono","it":"Un semitono"}},{"id":"whole","label":{"en":"A whole step","fr":"Un ton","es":"Un tono","it":"Un tono"}}],"prompt":{"en":"Listen to the two notes: are they a half step or a whole step apart?","fr":"Écoute les deux notes : sont-elles à un demi-ton ou à un ton d'écart ?","es":"Escucha las dos notas: ¿están a un semitono o a un tono de distancia?","it":"Ascolta le due note: distano un semitono o un tono?"}},{"type":"earChoice","notes":["C4","D4"],"answerId":"whole","choices":[{"id":"half","label":{"en":"A half step","fr":"Un demi-ton","es":"Un semitono","it":"Un semitono"}},{"id":"whole","label":{"en":"A whole step","fr":"Un ton","es":"Un tono","it":"Un tono"}}],"prompt":{"en":"Same game, new pair: half step or whole step?","fr":"Même jeu, nouvelle paire : demi-ton ou ton ?","es":"Mismo juego, otro par: ¿semitono o tono?","it":"Stesso gioco, nuova coppia: semitono o tono?"}},{"type":"question","prompt":{"en":"Between E and F, how big is the step?","fr":"Entre mi et fa, quel est l'écart ?","es":"Entre mi y fa, ¿cuál es la distancia?","it":"Tra mi e fa, qual è la distanza?"},"options":[{"en":"A half step — they are direct neighbors","fr":"Un demi-ton — ce sont des voisines directes","es":"Un semitono — son vecinas directas","it":"Un semitono — sono vicine dirette"},{"en":"A whole step — a black key sits between them","fr":"Un ton — une touche noire les sépare","es":"Un tono — una tecla negra las separa","it":"Un tono — un tasto nero le separa"}],"answerIndex":0,"feedback":{"en":"Exactly: E–F (like B–C) has no black key in between, so it is a half step.","fr":"Exactement : entre mi et fa (comme entre si et do), pas de touche noire — c'est un demi-ton.","es":"Exacto: entre mi y fa (como entre si y do) no hay tecla negra — es un semitono.","it":"Esatto: tra mi e fa (come tra si e do) non c'è tasto nero — è un semitono."},"keyboard":true},{"type":"text","text":{"en":"You can now hear and name the two step sizes. Remember: E–F and B–C are the only white-key half steps.","fr":"Tu sais maintenant entendre et nommer le ton et le demi-ton. Retiens : mi–fa et si–do sont les seuls demi-tons entre touches blanches.","es":"Ya sabes escuchar y nombrar el tono y el semitono. Recuerda: mi–fa y si–do son los únicos semitonos entre teclas blancas.","it":"Ora sai ascoltare e nominare il tono e il semitono. Ricorda: mi–fa e si–do sono gli unici semitoni tra tasti bianchi."}}]}$cymbra$
),
(
  'sol-u6-02-le-diese', 'published', 'piano', 'solfege', 'intermediate',
  'u6', $cymbra${"en":"Sharps, flats and keys","fr":"Dièses, bémols et tonalités","es":"Sostenidos, bemoles y tonalidades","it":"Diesis, bemolli e tonalità"}$cymbra$, 602, 2,
  $cymbra${"en":"The sharp","fr":"Le dièse","es":"El sostenido","it":"Il diesis"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u6-02-le-diese","instrument":"piano","track":"solfege","level":"intermediate","title":{"en":"The sharp","fr":"Le dièse","es":"El sostenido","it":"Il diesis"},"summary":{"en":"The sharp raises a note by a half step","fr":"Le dièse monte la note d'un demi-ton","es":"El sostenido sube la nota un semitono","it":"Il diesis alza la nota di un semitono"},"blocks":[{"type":"text","text":{"en":"A sharp (♯) raises a note by a half step — on the piano, that is usually the black key just to the right. Meet your first one: F♯.","fr":"Le dièse (♯) monte la note d'un demi-ton — au piano, c'est souvent la touche noire juste à droite. Voici ton premier : fa dièse.","es":"El sostenido (♯) sube la nota un semitono — en el piano suele ser la tecla negra justo a la derecha. Aquí tienes el primero: fa sostenido.","it":"Il diesis (♯) alza la nota di un semitono — al pianoforte è di solito il tasto nero subito a destra. Ecco il tuo primo: fa diesis."}},{"type":"staff","clef":"treble","labels":true,"elements":[{"p":"F4","fig":"quarter"},{"p":"F#4","fig":"quarter"}],"caption":{"en":"F and F♯ sit in the same spot on the staff — only the ♯ tells you to play a half step higher.","fr":"Fa et fa♯ occupent la même place sur la portée — seul le ♯ t'indique de jouer un demi-ton plus haut.","es":"Fa y fa♯ ocupan el mismo lugar en el pentagrama — solo el ♯ te indica tocar un semitono más alto.","it":"Fa e fa♯ occupano lo stesso posto sul pentagramma — solo il ♯ ti dice di suonare un semitono più in alto."}},{"type":"readPlay","mode":"drill","clef":"treble","labels":"always","notes":["F4","F#4"],"prompt":{"en":"Play the note shown — for F♯, reach for the black key just right of F.","fr":"Joue la note affichée — pour fa♯, vise la touche noire juste à droite de fa.","es":"Toca la nota que se muestra — para fa♯, busca la tecla negra justo a la derecha de fa.","it":"Suona la nota mostrata — per fa♯, cerca il tasto nero subito a destra di fa."}},{"type":"nameNote","clef":"treble","notes":["F#4","G#4"],"prompt":{"en":"Name this note — check whether a ♯ stands in front of it.","fr":"Nomme cette note — regarde bien si un ♯ la précède.","es":"Nombra esta nota — fíjate si lleva un ♯ delante.","it":"Dai il nome a questa nota — controlla se c'è un ♯ davanti."}},{"type":"earChoice","notes":["F4","F#4"],"answerId":"up","choices":[{"id":"up","label":{"en":"Higher","fr":"Plus aiguë","es":"Más aguda","it":"Più acuta"}},{"id":"down","label":{"en":"Lower","fr":"Plus grave","es":"Más grave","it":"Più grave"}}],"prompt":{"en":"Listen to F, then its sharp: is the second note higher or lower?","fr":"Écoute fa, puis son dièse : la deuxième note est-elle plus aiguë ou plus grave ?","es":"Escucha fa y luego su sostenido: ¿la segunda nota es más aguda o más grave?","it":"Ascolta fa e poi il suo diesis: la seconda nota è più acuta o più grave?"}},{"type":"question","prompt":{"en":"What does a sharp do to a note?","fr":"Que fait le dièse à une note ?","es":"¿Qué le hace el sostenido a una nota?","it":"Che cosa fa il diesis a una nota?"},"options":[{"en":"It raises it by a half step","fr":"Il la monte d'un demi-ton","es":"La sube un semitono","it":"La alza di un semitono"},{"en":"It lowers it by a half step","fr":"Il la descend d'un demi-ton","es":"La baja un semitono","it":"La abbassa di un semitono"}],"answerIndex":0,"feedback":{"en":"Right — the sharp always pushes the note a half step up.","fr":"C'est ça — le dièse pousse toujours la note un demi-ton plus haut.","es":"Eso es — el sostenido siempre empuja la nota un semitono hacia arriba.","it":"Proprio così — il diesis spinge sempre la nota un semitono più in alto."}},{"type":"text","text":{"en":"You just read and played your first sharps. F♯ and G♯ are half steps up from F and G — the ♯ sign makes it official.","fr":"Tu viens de lire et de jouer tes premiers dièses. Fa♯ et sol♯ sont un demi-ton au-dessus de fa et sol — le signe ♯ le rend officiel.","es":"Acabas de leer y tocar tus primeros sostenidos. Fa♯ y sol♯ están un semitono por encima de fa y sol — el signo ♯ lo hace oficial.","it":"Hai appena letto e suonato i tuoi primi diesis. Fa♯ e sol♯ sono un semitono sopra fa e sol — il segno ♯ lo rende ufficiale."}}]}$cymbra$
),
(
  'sol-u6-03-le-bemol-et-le-becarre', 'published', 'piano', 'solfege', 'intermediate',
  'u6', $cymbra${"en":"Sharps, flats and keys","fr":"Dièses, bémols et tonalités","es":"Sostenidos, bemoles y tonalidades","it":"Diesis, bemolli e tonalità"}$cymbra$, 603, 2,
  $cymbra${"en":"Flat and natural","fr":"Le bémol et le bécarre","es":"El bemol y el becuadro","it":"Il bemolle e il bequadro"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u6-03-le-bemol-et-le-becarre","instrument":"piano","track":"solfege","level":"intermediate","title":{"en":"Flat and natural","fr":"Le bémol et le bécarre","es":"El bemol y el becuadro","it":"Il bemolle e il bequadro"},"summary":{"en":"The flat lowers, the natural cancels","fr":"Le bémol descend, le bécarre annule","es":"El bemol baja, el becuadro anula","it":"Il bemolle abbassa, il bequadro annulla"},"blocks":[{"type":"text","text":{"en":"A flat (♭) lowers a note by a half step — usually the black key just to the left. And the natural sign (♮) cancels any sharp or flat.","fr":"Le bémol (♭) descend la note d'un demi-ton — souvent la touche noire juste à gauche. Et le bécarre (♮) annule tout dièse ou bémol.","es":"El bemol (♭) baja la nota un semitono — a menudo la tecla negra justo a la izquierda. Y el becuadro (♮) anula cualquier sostenido o bemol.","it":"Il bemolle (♭) abbassa la nota di un semitono — spesso il tasto nero subito a sinistra. E il bequadro (♮) annulla qualsiasi diesis o bemolle."}},{"type":"staff","clef":"treble","labels":true,"elements":[{"p":"B4","fig":"quarter"},{"p":"Bb4","fig":"quarter"}],"caption":{"en":"B and B♭ share the middle line — the ♭ tells you to slide a half step down.","fr":"Si et si♭ partagent la ligne du milieu — le ♭ t'invite à glisser un demi-ton plus bas.","es":"Si y si♭ comparten la línea central — el ♭ te pide bajar un semitono.","it":"Si e si♭ condividono la linea centrale — il ♭ ti chiede di scendere di un semitono."}},{"type":"readPlay","mode":"drill","clef":"treble","labels":"always","notes":["B4","Bb4"],"prompt":{"en":"Play the note shown — for B♭, take the black key just left of B.","fr":"Joue la note affichée — pour si♭, prends la touche noire juste à gauche de si.","es":"Toca la nota que se muestra — para si♭, usa la tecla negra justo a la izquierda de si.","it":"Suona la nota mostrata — per si♭, prendi il tasto nero subito a sinistra di si."}},{"type":"nameNote","clef":"treble","notes":["Bb4","Eb4"],"prompt":{"en":"Name this note — the ♭ in front is part of its name.","fr":"Nomme cette note — le ♭ devant fait partie de son nom.","es":"Nombra esta nota — el ♭ delante forma parte de su nombre.","it":"Dai il nome a questa nota — il ♭ davanti fa parte del suo nome."}},{"type":"earChoice","notes":["E4","Eb4"],"answerId":"down","choices":[{"id":"up","label":{"en":"Higher","fr":"Plus aiguë","es":"Más aguda","it":"Più acuta"}},{"id":"down","label":{"en":"Lower","fr":"Plus grave","es":"Más grave","it":"Più grave"}}],"prompt":{"en":"Listen to E, then its flat: is the second note higher or lower?","fr":"Écoute mi, puis son bémol : la deuxième note est-elle plus aiguë ou plus grave ?","es":"Escucha mi y luego su bemol: ¿la segunda nota es más aguda o más grave?","it":"Ascolta mi e poi il suo bemolle: la seconda nota è più acuta o più grave?"}},{"type":"question","prompt":{"en":"What does the natural sign (♮) do?","fr":"Que fait le bécarre (♮) ?","es":"¿Qué hace el becuadro (♮)?","it":"Che cosa fa il bequadro (♮)?"},"options":[{"en":"It cancels a sharp or a flat","fr":"Il annule un dièse ou un bémol","es":"Anula un sostenido o un bemol","it":"Annulla un diesis o un bemolle"},{"en":"It doubles the alteration","fr":"Il double l'altération","es":"Duplica la alteración","it":"Raddoppia l'alterazione"}],"answerIndex":0,"feedback":{"en":"Exactly — a natural brings the note back to its plain, unaltered self.","fr":"Exactement — le bécarre ramène la note à sa version naturelle, sans altération.","es":"Exacto — el becuadro devuelve la nota a su versión natural, sin alteración.","it":"Esatto — il bequadro riporta la nota alla sua versione naturale, senza alterazione."}},{"type":"text","text":{"en":"Flats go down, sharps go up, naturals cancel. You can now read B♭ and E♭ — and hear what the flat does.","fr":"Le bémol descend, le dièse monte, le bécarre annule. Tu sais maintenant lire si♭ et mi♭ — et entendre l'effet du bémol.","es":"El bemol baja, el sostenido sube, el becuadro anula. Ya sabes leer si♭ y mi♭ — y oír el efecto del bemol.","it":"Il bemolle scende, il diesis sale, il bequadro annulla. Ora sai leggere si♭ e mi♭ — e sentire l'effetto del bemolle."}}]}$cymbra$
),
(
  'sol-u6-04-la-gamme-majeure', 'published', 'piano', 'solfege', 'intermediate',
  'u6', $cymbra${"en":"Sharps, flats and keys","fr":"Dièses, bémols et tonalités","es":"Sostenidos, bemoles y tonalidades","it":"Diesis, bemolli e tonalità"}$cymbra$, 604, 2,
  $cymbra${"en":"The major scale","fr":"La gamme majeure","es":"La escala mayor","it":"La scala maggiore"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u6-04-la-gamme-majeure","instrument":"piano","track":"solfege","level":"intermediate","title":{"en":"The major scale","fr":"La gamme majeure","es":"La escala mayor","it":"La scala maggiore"},"summary":{"en":"The whole/half-step recipe behind C major","fr":"La recette de tons et demi-tons derrière do majeur","es":"La receta de tonos y semitonos detrás de do mayor","it":"La ricetta di toni e semitoni dietro do maggiore"},"blocks":[{"type":"text","text":{"en":"A major scale is a recipe of steps: whole, whole, half, whole, whole, whole, half. Start on C and the recipe uses only white keys.","fr":"Une gamme majeure est une recette d'écarts : ton, ton, demi-ton, ton, ton, ton, demi-ton. En partant de do, la recette n'utilise que des touches blanches.","es":"Una escala mayor es una receta de distancias: tono, tono, semitono, tono, tono, tono, semitono. Empezando en do, la receta solo usa teclas blancas.","it":"Una scala maggiore è una ricetta di distanze: tono, tono, semitono, tono, tono, tono, semitono. Partendo da do, la ricetta usa solo tasti bianchi."}},{"type":"staff","clef":"treble","labels":true,"elements":[{"p":"C4","fig":"quarter"},{"p":"D4","fig":"quarter"},{"p":"E4","fig":"quarter"},{"p":"F4","fig":"quarter"},{"p":"G4","fig":"quarter"},{"p":"A4","fig":"quarter"},{"p":"B4","fig":"quarter"},{"p":"C5","fig":"quarter"}],"caption":{"en":"The C major scale — its half steps fall between E–F and B–C.","fr":"La gamme de do majeur — ses demi-tons tombent entre mi–fa et si–do.","es":"La escala de do mayor — sus semitonos caen entre mi–fa y si–do.","it":"La scala di do maggiore — i suoi semitoni cadono tra mi–fa e si–do."}},{"type":"readPlay","mode":"melody","clef":"treble","labels":"afterMiss","notes":["C4","D4","E4","F4","G4","A4","B4","C5"],"prompt":{"en":"Play the whole C major scale, from C to C, left to right.","fr":"Joue toute la gamme de do majeur, de do à do, de gauche à droite.","es":"Toca la escala de do mayor completa, de do a do, de izquierda a derecha.","it":"Suona tutta la scala di do maggiore, da do a do, da sinistra a destra."}},{"type":"question","prompt":{"en":"In a major scale, where do the half steps sit?","fr":"Dans une gamme majeure, où se placent les demi-tons ?","es":"En una escala mayor, ¿dónde se colocan los semitonos?","it":"In una scala maggiore, dove si trovano i semitoni?"},"options":[{"en":"Between degrees 3–4 and 7–8","fr":"Entre les degrés 3–4 et 7–8","es":"Entre los grados 3–4 y 7–8","it":"Tra i gradi 3–4 e 7–8"},{"en":"Between degrees 1–2 and 4–5","fr":"Entre les degrés 1–2 et 4–5","es":"Entre los grados 1–2 y 4–5","it":"Tra i gradi 1–2 e 4–5"}],"answerIndex":0,"feedback":{"en":"Right — in C major that is E–F and B–C, the two white-key half steps.","fr":"C'est ça — en do majeur, ce sont mi–fa et si–do, les deux demi-tons entre touches blanches.","es":"Eso es — en do mayor son mi–fa y si–do, los dos semitonos entre teclas blancas.","it":"Proprio così — in do maggiore sono mi–fa e si–do, i due semitoni tra tasti bianchi."}},{"type":"earChoice","notes":["E4","F4"],"answerId":"half","choices":[{"id":"half","label":{"en":"A half step","fr":"Un demi-ton","es":"Un semitono","it":"Un semitono"}},{"id":"whole","label":{"en":"A whole step","fr":"Un ton","es":"Un tono","it":"Un tono"}}],"prompt":{"en":"Here is one step from the scale: half or whole?","fr":"Voici un écart de la gamme : demi-ton ou ton ?","es":"Aquí tienes una distancia de la escala: ¿semitono o tono?","it":"Ecco una distanza della scala: semitono o tono?"}},{"type":"earChoice","notes":["G4","A4"],"answerId":"whole","choices":[{"id":"half","label":{"en":"A half step","fr":"Un demi-ton","es":"Un semitono","it":"Un semitono"}},{"id":"whole","label":{"en":"A whole step","fr":"Un ton","es":"Un tono","it":"Un tono"}}],"prompt":{"en":"One more step from the scale: half or whole?","fr":"Encore un écart de la gamme : demi-ton ou ton ?","es":"Otra distancia de la escala: ¿semitono o tono?","it":"Un'altra distanza della scala: semitono o tono?"}},{"type":"text","text":{"en":"You played the whole C major scale and spotted its recipe. The half steps hide between degrees 3–4 and 7–8 — everywhere else, whole steps.","fr":"Tu as joué toute la gamme de do majeur et repéré sa recette. Les demi-tons se cachent entre les degrés 3–4 et 7–8 — partout ailleurs, des tons.","es":"Tocaste la escala de do mayor completa y descubriste su receta. Los semitonos se esconden entre los grados 3–4 y 7–8 — en el resto, tonos.","it":"Hai suonato tutta la scala di do maggiore e scoperto la sua ricetta. I semitoni si nascondono tra i gradi 3–4 e 7–8 — altrove, toni."}}]}$cymbra$
),
(
  'sol-u6-05-l-armure', 'published', 'piano', 'solfege', 'intermediate',
  'u6', $cymbra${"en":"Sharps, flats and keys","fr":"Dièses, bémols et tonalités","es":"Sostenidos, bemoles y tonalidades","it":"Diesis, bemolli e tonalità"}$cymbra$, 605, 2,
  $cymbra${"en":"Key signatures: G and F major","fr":"L'armure : sol majeur et fa majeur","es":"La armadura: sol mayor y fa mayor","it":"L'armatura: sol maggiore e fa maggiore"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u6-05-l-armure","instrument":"piano","track":"solfege","level":"intermediate","title":{"en":"Key signatures: G and F major","fr":"L'armure : sol majeur et fa majeur","es":"La armadura: sol mayor y fa mayor","it":"L'armatura: sol maggiore e fa maggiore"},"summary":{"en":"One sign at the clef alters the whole piece","fr":"Un signe à la clé altère toute la pièce","es":"Un signo junto a la clave altera toda la pieza","it":"Un segno alla chiave altera tutto il brano"},"blocks":[{"type":"text","text":{"en":"Start the scale recipe on G and you need one F♯; start on F and you need one B♭. Instead of rewriting the sign every time, the key signature writes it once, right after the clef.","fr":"Commence la recette de la gamme sur sol et il te faut un fa♯ ; commence sur fa et il te faut un si♭. Plutôt que de réécrire le signe à chaque fois, l'armure l'écrit une seule fois, juste après la clé.","es":"Empieza la receta de la escala en sol y necesitas un fa♯; empieza en fa y necesitas un si♭. En vez de reescribir el signo cada vez, la armadura lo escribe una sola vez, justo después de la clave.","it":"Inizia la ricetta della scala da sol e ti serve un fa♯; inizia da fa e ti serve un si♭. Invece di riscrivere il segno ogni volta, l'armatura lo scrive una sola volta, subito dopo la chiave."}},{"type":"staff","clef":"treble","keyFifths":1,"elements":[{"p":"G4","fig":"quarter"},{"p":"A4","fig":"quarter"},{"p":"B4","fig":"quarter"},{"p":"C5","fig":"quarter"},{"p":"D5","fig":"quarter"},{"p":"E5","fig":"quarter"},{"p":"F#5","fig":"quarter"},{"p":"G5","fig":"quarter"}],"caption":{"en":"G major: one sharp at the clef — every F is now F♯, and nothing is rewritten on the notes.","fr":"Sol majeur : un dièse à la clé — chaque fa devient fa♯, et rien n'est réécrit sur les notes.","es":"Sol mayor: un sostenido junto a la clave — cada fa se vuelve fa♯, y nada se reescribe en las notas.","it":"Sol maggiore: un diesis alla chiave — ogni fa diventa fa♯, e nulla è riscritto sulle note."}},{"type":"readPlay","mode":"drill","clef":"treble","keyFifths":1,"labels":"always","notes":["F#5"],"prompt":{"en":"The staff shows a plain F on the top line — but the key signature makes it F♯. Play it.","fr":"La portée montre un fa tout simple sur la dernière ligne — mais l'armure en fait un fa♯. Joue-le.","es":"El pentagrama muestra un fa normal en la última línea — pero la armadura lo convierte en fa♯. Tócalo.","it":"Il pentagramma mostra un fa semplice sull'ultima riga — ma l'armatura lo rende fa♯. Suonalo."}},{"type":"readPlay","mode":"melody","clef":"treble","keyFifths":1,"labels":"never","notes":["G4","A4","B4","C5","D5"],"prompt":{"en":"Play the opening of the G major scale, left to right.","fr":"Joue le début de la gamme de sol majeur, de gauche à droite.","es":"Toca el comienzo de la escala de sol mayor, de izquierda a derecha.","it":"Suona l'inizio della scala di sol maggiore, da sinistra a destra."}},{"type":"staff","clef":"treble","keyFifths":-1,"elements":[{"p":"F4","fig":"quarter"},{"p":"G4","fig":"quarter"},{"p":"A4","fig":"quarter"},{"p":"Bb4","fig":"quarter"}],"caption":{"en":"F major: one flat at the clef — every B is now B♭.","fr":"Fa majeur : un bémol à la clé — chaque si devient si♭.","es":"Fa mayor: un bemol junto a la clave — cada si se vuelve si♭.","it":"Fa maggiore: un bemolle alla chiave — ogni si diventa si♭."}},{"type":"readPlay","mode":"drill","clef":"treble","keyFifths":-1,"labels":"always","notes":["Bb4"],"prompt":{"en":"The staff shows a plain B — the key signature already made it B♭. Play the black key.","fr":"La portée montre un si tout simple — l'armure en a déjà fait un si♭. Joue la touche noire.","es":"El pentagrama muestra un si normal — la armadura ya lo convirtió en si♭. Toca la tecla negra.","it":"Il pentagramma mostra un si semplice — l'armatura lo ha già reso si♭. Suona il tasto nero."}},{"type":"question","prompt":{"en":"What does the key signature do?","fr":"Que fait l'armure ?","es":"¿Qué hace la armadura?","it":"Che cosa fa l'armatura?"},"options":[{"en":"It alters its notes once, for the whole piece","fr":"Elle altère ses notes une fois pour toute la pièce","es":"Altera sus notas una vez para toda la pieza","it":"Altera le sue note una volta per tutto il brano"},{"en":"It alters only the first note after the clef","fr":"Elle n'altère que la première note après la clé","es":"Solo altera la primera nota después de la clave","it":"Altera solo la prima nota dopo la chiave"}],"answerIndex":0,"feedback":{"en":"Right — one sharp at the clef and every F in the piece is F♯, in every octave.","fr":"C'est ça — un dièse à la clé, et chaque fa de la pièce devient fa♯, à toutes les octaves.","es":"Eso es — un sostenido junto a la clave y cada fa de la pieza es fa♯, en todas las octavas.","it":"Proprio così — un diesis alla chiave e ogni fa del brano è fa♯, in tutte le ottave."}},{"type":"text","text":{"en":"You read your first key signatures: G major with its F♯, F major with its B♭. One sign at the clef, and the whole piece follows.","fr":"Tu as lu tes premières armures : sol majeur avec son fa♯, fa majeur avec son si♭. Un signe à la clé, et toute la pièce suit.","es":"Leíste tus primeras armaduras: sol mayor con su fa♯, fa mayor con su si♭. Un signo junto a la clave, y toda la pieza obedece.","it":"Hai letto le tue prime armature: sol maggiore con il suo fa♯, fa maggiore con il suo si♭. Un segno alla chiave, e tutto il brano segue."}}]}$cymbra$
),
(
  'sol-u6-06-bilan-alterations', 'published', 'piano', 'solfege', 'intermediate',
  'u6', $cymbra${"en":"Sharps, flats and keys","fr":"Dièses, bémols et tonalités","es":"Sostenidos, bemoles y tonalidades","it":"Diesis, bemolli e tonalità"}$cymbra$, 606, 2,
  $cymbra${"en":"Checkpoint: accidentals","fr":"Bilan : les altérations","es":"Repaso: las alteraciones","it":"Ripasso: le alterazioni"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u6-06-bilan-alterations","instrument":"piano","track":"solfege","level":"intermediate","title":{"en":"Checkpoint: accidentals","fr":"Bilan : les altérations","es":"Repaso: las alteraciones","it":"Ripasso: le alterazioni"},"summary":{"en":"Review sharps, flats and key signatures","fr":"Réviser dièses, bémols et armures","es":"Repasar sostenidos, bemoles y armaduras","it":"Ripassare diesis, bemolli e armature"},"blocks":[{"type":"text","text":{"en":"Time to put it all together: sharps, flats, half steps and key signatures. Show what your eyes and ears have learned.","fr":"L'heure du bilan : dièses, bémols, demi-tons et armures. Montre ce que tes yeux et tes oreilles ont appris.","es":"Hora de juntarlo todo: sostenidos, bemoles, semitonos y armaduras. Demuestra lo que tus ojos y tus oídos han aprendido.","it":"È il momento di mettere tutto insieme: diesis, bemolli, semitoni e armature. Mostra che cosa hanno imparato i tuoi occhi e le tue orecchie."}},{"type":"nameNote","clef":"treble","choiceCount":3,"notes":["F#4","Bb4","C#4"],"prompt":{"en":"Name each note — mind the sign in front: ♯ or ♭?","fr":"Nomme chaque note — attention au signe devant : ♯ ou ♭ ?","es":"Nombra cada nota — atención al signo delante: ¿♯ o ♭?","it":"Dai il nome a ogni nota — occhio al segno davanti: ♯ o ♭?"}},{"type":"readPlay","mode":"drill","clef":"treble","labels":"never","notes":["F#4","Bb4","E4"],"prompt":{"en":"Play the note shown — no labels this time, your reading has got this.","fr":"Joue la note affichée — sans étiquettes cette fois, ta lecture est prête.","es":"Toca la nota que se muestra — sin etiquetas esta vez, tu lectura ya puede sola.","it":"Suona la nota mostrata — senza etichette questa volta, la tua lettura è pronta."}},{"type":"earChoice","notes":["B4","Bb4"],"answerId":"down","choices":[{"id":"up","label":{"en":"Higher","fr":"Plus aiguë","es":"Más aguda","it":"Più acuta"}},{"id":"down","label":{"en":"Lower","fr":"Plus grave","es":"Más grave","it":"Più grave"}}],"prompt":{"en":"Listen to B, then its flat: is the second note higher or lower?","fr":"Écoute si, puis son bémol : la deuxième note est-elle plus aiguë ou plus grave ?","es":"Escucha si y luego su bemol: ¿la segunda nota es más aguda o más grave?","it":"Ascolta si e poi il suo bemolle: la seconda nota è più acuta o più grave?"}},{"type":"question","prompt":{"en":"A key signature with one flat: which note does it change?","fr":"Une armure avec un bémol : quelle note change-t-elle ?","es":"Una armadura con un bemol: ¿qué nota cambia?","it":"Un'armatura con un bemolle: quale nota cambia?"},"options":[{"en":"Every B, for the whole piece","fr":"Tous les si, pour toute la pièce","es":"Todos los si, durante toda la pieza","it":"Tutti i si, per tutto il brano"},{"en":"Only the very next note","fr":"Seulement la note qui suit","es":"Solo la nota siguiente","it":"Solo la nota successiva"}],"answerIndex":0,"feedback":{"en":"Right — that is F major's signature: every B becomes B♭ until the end.","fr":"C'est ça — c'est l'armure de fa majeur : chaque si devient si♭ jusqu'à la fin.","es":"Eso es — es la armadura de fa mayor: cada si se vuelve si♭ hasta el final.","it":"Proprio così — è l'armatura di fa maggiore: ogni si diventa si♭ fino alla fine."}},{"type":"text","text":{"en":"Checkpoint cleared! You read, play and hear sharps and flats — and a key signature holds no secrets for you.","fr":"Bilan réussi ! Tu lis, joues et entends les dièses et les bémols — et l'armure n'a plus de secret pour toi.","es":"¡Repaso superado! Lees, tocas y oyes sostenidos y bemoles — y la armadura ya no tiene secretos para ti.","it":"Ripasso superato! Leggi, suoni e senti diesis e bemolli — e l'armatura non ha più segreti per te."}}]}$cymbra$
),
(
  'sol-u7-01-secondes-et-tierces-a-l-oreille', 'published', 'piano', 'solfege', 'advanced',
  'u7', $cymbra${"en":"Intervals, chords and ear","fr":"Intervalles, accords et oreille","es":"Intervalos, acordes y oído","it":"Intervalli, accordi e orecchio"}$cymbra$, 701, 2,
  $cymbra${"en":"Seconds and thirds by ear","fr":"Secondes et tierces à l'oreille","es":"Segundas y terceras de oído","it":"Seconde e terze a orecchio"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u7-01-secondes-et-tierces-a-l-oreille","instrument":"piano","track":"solfege","level":"advanced","title":{"en":"Seconds and thirds by ear","fr":"Secondes et tierces à l'oreille","es":"Segundas y terceras de oído","it":"Seconde e terze a orecchio"},"summary":{"en":"Tell seconds from thirds by ear","fr":"Distinguer secondes et tierces à l'oreille","es":"Distinguir segundas y terceras de oído","it":"Distinguere seconde e terze a orecchio"},"blocks":[{"type":"text","text":{"en":"A second steps to the neighbour note; a third skips over one. Your ear can learn to tell them apart in a heartbeat.","fr":"Une seconde avance vers la note voisine ; une tierce en saute une. Ton oreille peut apprendre à les distinguer en un battement.","es":"Una segunda avanza a la nota vecina; una tercera se salta una. Tu oído puede aprender a distinguirlas en un instante.","it":"Una seconda passa alla nota vicina; una terza ne salta una. Il tuo orecchio può imparare a distinguerle in un attimo."}},{"type":"staff","clef":"treble","elements":[{"p":"C4","fig":"quarter"},{"p":"D4","fig":"quarter"},{"p":"C4","fig":"quarter"},{"p":"E4","fig":"quarter"}],"caption":{"en":"C to D is a second, C to E is a third — see them here, then hear them.","fr":"Do–ré est une seconde, do–mi une tierce — regarde-les ici, puis écoute-les.","es":"Do–re es una segunda, do–mi una tercera: míralas aquí y luego escúchalas.","it":"Do–re è una seconda, do–mi una terza: guardale qui, poi ascoltale."}},{"type":"earChoice","notes":["C4","D4"],"answerId":"second","choices":[{"id":"second","label":{"en":"A second","fr":"Une seconde","es":"Una segunda","it":"Una seconda"}},{"id":"third","label":{"en":"A third","fr":"Une tierce","es":"Una tercera","it":"Una terza"}}],"prompt":{"en":"Listen: C climbs to its neighbour D. Which interval is that?","fr":"Écoute : do monte vers sa voisine ré. Quel est cet intervalle ?","es":"Escucha: do sube a su vecina re. ¿Qué intervalo es?","it":"Ascolta: do sale alla vicina re. Che intervallo è?"}},{"type":"earChoice","notes":["C4","E4"],"answerId":"third","choices":[{"id":"second","label":{"en":"A second","fr":"Une seconde","es":"Una segunda","it":"Una seconda"}},{"id":"third","label":{"en":"A third","fr":"Une tierce","es":"Una tercera","it":"Una terza"}}],"prompt":{"en":"Now C jumps over D and lands on E. What do you hear?","fr":"Maintenant do saute par-dessus ré et atterrit sur mi. Qu'entends-tu ?","es":"Ahora do salta por encima de re y cae en mi. ¿Qué escuchas?","it":"Ora do salta sopra re e atterra su mi. Cosa senti?"}},{"type":"earChoice","notes":["E4","F4"],"answerId":"second","choices":[{"id":"second","label":{"en":"A second","fr":"Une seconde","es":"Una segunda","it":"Una seconda"}},{"id":"third","label":{"en":"A third","fr":"Une tierce","es":"Una tercera","it":"Una terza"}}],"prompt":{"en":"No hints this time — new notes. Step or skip: which interval is it?","fr":"Sans indice cette fois — d'autres notes. Un pas ou un saut : quel est cet intervalle ?","es":"Sin pistas esta vez, con otras notas. ¿Paso o salto: qué intervalo es?","it":"Senza aiuti questa volta, con altre note. Passo o salto: che intervallo è?"}},{"type":"readPlay","mode":"melody","clef":"treble","labels":"never","notes":["C4","E4","D4","F4","E4","G4"],"prompt":{"en":"Play this chain of broken thirds climbing up the staff.","fr":"Joue cette chaîne de tierces brisées qui grimpe sur la portée.","es":"Toca esta cadena de terceras quebradas que sube por el pentagrama.","it":"Suona questa catena di terze spezzate che sale sul pentagramma."}},{"type":"text","text":{"en":"Bravo! A second steps, a third skips — and your ear now knows it before your eyes do.","fr":"Bravo ! Une seconde avance d'un pas, une tierce saute — et ton oreille le sait désormais avant tes yeux.","es":"¡Bravo! Una segunda avanza un paso, una tercera salta — y tu oído ya lo sabe antes que tus ojos.","it":"Bravo! Una seconda fa un passo, una terza salta — e il tuo orecchio ormai lo sa prima dei tuoi occhi."}}]}$cymbra$
),
(
  'sol-u7-02-quartes-et-quintes', 'published', 'piano', 'solfege', 'advanced',
  'u7', $cymbra${"en":"Intervals, chords and ear","fr":"Intervalles, accords et oreille","es":"Intervalos, acordes y oído","it":"Intervalli, accordi e orecchio"}$cymbra$, 702, 2,
  $cymbra${"en":"Fourths and fifths","fr":"Quartes et quintes","es":"Cuartas y quintas","it":"Quarte e quinte"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u7-02-quartes-et-quintes","instrument":"piano","track":"solfege","level":"advanced","title":{"en":"Fourths and fifths","fr":"Quartes et quintes","es":"Cuartas y quintas","it":"Quarte e quinte"},"summary":{"en":"Hear and play fourths and fifths","fr":"Entendre et jouer quartes et quintes","es":"Escuchar y tocar cuartas y quintas","it":"Sentire e suonare quarte e quinte"},"blocks":[{"type":"text","text":{"en":"Wider leaps now: the fourth and the fifth, the intervals fanfares are built on. Big, open, easy to love.","fr":"Des sauts plus larges maintenant : la quarte et la quinte, les intervalles des fanfares. Grands, ouverts, faciles à aimer.","es":"Ahora saltos más amplios: la cuarta y la quinta, los intervalos de las fanfarrias. Grandes, abiertos, fáciles de querer.","it":"Ora salti più ampi: la quarta e la quinta, gli intervalli delle fanfare. Grandi, aperti, facili da amare."}},{"type":"staff","clef":"treble","elements":[{"p":"C4","fig":"quarter"},{"p":"F4","fig":"quarter"},{"p":"C4","fig":"quarter"},{"p":"G4","fig":"quarter"}],"caption":{"en":"C to F spans four steps: a fourth. C to G spans five: a fifth.","fr":"De do à fa, quatre degrés : une quarte. De do à sol, cinq : une quinte.","es":"De do a fa, cuatro grados: una cuarta. De do a sol, cinco: una quinta.","it":"Da do a fa, quattro gradi: una quarta. Da do a sol, cinque: una quinta."}},{"type":"earChoice","notes":["C4","F4"],"answerId":"fourth","choices":[{"id":"fourth","label":{"en":"A fourth","fr":"Une quarte","es":"Una cuarta","it":"Una quarta"}},{"id":"fifth","label":{"en":"A fifth","fr":"Une quinte","es":"Una quinta","it":"Una quinta"}}],"prompt":{"en":"Listen: C leaps up to F. Which interval is that?","fr":"Écoute : do bondit jusqu'à fa. Quel est cet intervalle ?","es":"Escucha: do salta hasta fa. ¿Qué intervalo es?","it":"Ascolta: do balza fino a fa. Che intervallo è?"}},{"type":"earChoice","notes":["C4","G4"],"answerId":"fifth","choices":[{"id":"fourth","label":{"en":"A fourth","fr":"Une quarte","es":"Una cuarta","it":"Una quarta"}},{"id":"fifth","label":{"en":"A fifth","fr":"Une quinte","es":"Una quinta","it":"Una quinta"}}],"prompt":{"en":"One step wider: C leaps to G. What do you hear now?","fr":"Un degré plus loin : do bondit jusqu'à sol. Qu'entends-tu maintenant ?","es":"Un grado más lejos: do salta hasta sol. ¿Qué escuchas ahora?","it":"Un grado più in là: do balza fino a sol. Cosa senti adesso?"}},{"type":"readPlay","mode":"melody","clef":"treble","labels":"never","notes":["C4","F4","C4","G4","C4"],"prompt":{"en":"Play the two leaps back to back: up a fourth, home, up a fifth, home.","fr":"Joue les deux sauts à la suite : quarte, retour, quinte, retour.","es":"Toca los dos saltos seguidos: cuarta, a casa, quinta, a casa.","it":"Suona i due salti uno dopo l'altro: quarta, a casa, quinta, a casa."}},{"type":"question","prompt":{"en":"\"Twinkle, Twinkle, Little Star\" opens with two Cs leaping up. Which interval starts the tune?","fr":"« Ah ! vous dirai-je maman » commence par deux do qui bondissent vers le haut. Quel intervalle ouvre la chanson ?","es":"«Campanita del lugar» empieza con dos do que saltan hacia arriba. ¿Qué intervalo abre la canción?","it":"«Brilla brilla la stellina» inizia con due do che balzano in su. Quale intervallo apre la canzone?"},"options":[{"en":"A fifth","fr":"Une quinte","es":"Una quinta","it":"Una quinta"},{"en":"A fourth","fr":"Une quarte","es":"Una cuarta","it":"Una quarta"}],"answerIndex":0,"feedback":{"en":"Yes — C up to G, the very fifth you just played.","fr":"Oui — de do à sol, exactement la quinte que tu viens de jouer.","es":"Sí: de do a sol, justo la quinta que acabas de tocar.","it":"Sì: da do a sol, proprio la quinta che hai appena suonato."}},{"type":"text","text":{"en":"A fourth leaps four steps, a fifth leaps five — and now you can hear which is which. Two more intervals in your pocket!","fr":"La quarte franchit quatre degrés, la quinte cinq — et tu sais maintenant les reconnaître à l'oreille. Deux intervalles de plus dans ta poche !","es":"La cuarta abarca cuatro grados, la quinta cinco — y ya sabes reconocerlas de oído. ¡Dos intervalos más en tu bolsillo!","it":"La quarta copre quattro gradi, la quinta cinque — e ora sai riconoscerle a orecchio. Altri due intervalli in tasca!"}}]}$cymbra$
),
(
  'sol-u7-03-la-triade-majeure', 'published', 'piano', 'solfege', 'advanced',
  'u7', $cymbra${"en":"Intervals, chords and ear","fr":"Intervalles, accords et oreille","es":"Intervalos, acordes y oído","it":"Intervalli, accordi e orecchio"}$cymbra$, 703, 2,
  $cymbra${"en":"The major triad","fr":"La triade majeure","es":"La tríada mayor","it":"La triade maggiore"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u7-03-la-triade-majeure","instrument":"piano","track":"solfege","level":"advanced","title":{"en":"The major triad","fr":"La triade majeure","es":"La tríada mayor","it":"La triade maggiore"},"summary":{"en":"Build the major triad on C and on G","fr":"Construire la triade majeure sur do et sur sol","es":"Construir la tríada mayor sobre do y sobre sol","it":"Costruire la triade maggiore su do e su sol"},"blocks":[{"type":"text","text":{"en":"Stack a third on top of a third and you get a chord: the major triad. It is the sound at the heart of most songs you know.","fr":"Empile une tierce sur une tierce et tu obtiens un accord : la triade majeure. C'est le son au cœur de presque toutes les chansons que tu connais.","es":"Apila una tercera sobre otra tercera y obtienes un acorde: la tríada mayor. Es el sonido en el corazón de casi todas las canciones que conoces.","it":"Impila una terza sopra un'altra terza e ottieni un accordo: la triade maggiore. È il suono al cuore di quasi tutte le canzoni che conosci."}},{"type":"staff","clef":"treble","labels":true,"elements":[{"p":"C4","fig":"quarter"},{"p":"E4","fig":"quarter"},{"p":"G4","fig":"quarter"}],"caption":{"en":"C, E, G — the pillars: degrees 1, 3 and 5 of the scale.","fr":"Do, mi, sol — les piliers : les degrés 1, 3 et 5 de la gamme.","es":"Do, mi, sol — los pilares: los grados 1, 3 y 5 de la escala.","it":"Do, mi, sol — i pilastri: i gradi 1, 3 e 5 della scala."}},{"type":"buildChord","notes":["C4","E4","G4"],"prompt":{"en":"Build C-E-G: press all three keys together and hear the triad ring.","fr":"Construis do-mi-sol : enfonce les trois touches ensemble et écoute sonner la triade.","es":"Construye do-mi-sol: pulsa las tres teclas a la vez y escucha sonar la tríada.","it":"Costruisci do-mi-sol: premi i tre tasti insieme e ascolta suonare la triade."}},{"type":"question","prompt":{"en":"A triad stacks which degrees of the scale?","fr":"Une triade empile quels degrés de la gamme ?","es":"¿Qué grados de la escala apila una tríada?","it":"Quali gradi della scala impila una triade?"},"options":[{"en":"1, 3 and 5","fr":"1, 3 et 5","es":"1, 3 y 5","it":"1, 3 e 5"},{"en":"1, 2 and 3","fr":"1, 2 et 3","es":"1, 2 y 3","it":"1, 2 e 3"}],"answerIndex":0,"feedback":{"en":"Right — you skip a step each time, and that stack of thirds is what makes it a chord.","fr":"Exact — on saute un degré à chaque fois, et c'est cet empilement de tierces qui fait l'accord.","es":"Exacto: se salta un grado cada vez, y ese apilado de terceras es lo que hace el acorde.","it":"Esatto: si salta un grado ogni volta, ed è quella pila di terze a fare l'accordo."}},{"type":"buildChord","notes":["G4","B4","D5"],"prompt":{"en":"Now build the G chord the same way: G, B and D, all together.","fr":"Maintenant construis l'accord de sol de la même façon : sol, si et ré, tous ensemble.","es":"Ahora construye el acorde de sol de la misma manera: sol, si y re, todos juntos.","it":"Ora costruisci l'accordo di sol allo stesso modo: sol, si e re, tutti insieme."}},{"type":"readPlay","mode":"melody","clef":"treble","labels":"never","notes":["C4","E4","G4","E4","C4"],"prompt":{"en":"Play the triad as a melody: climb the pillars, then come back down.","fr":"Joue la triade en mélodie : grimpe les piliers, puis redescends.","es":"Toca la tríada como melodía: sube por los pilares y vuelve a bajar.","it":"Suona la triade come melodia: sali sui pilastri, poi ridiscendi."}},{"type":"text","text":{"en":"You built your first chords: triads stacked 1-3-5, on C and on G. Songs are made of these.","fr":"Tu as construit tes premiers accords : des triades empilées 1-3-5, sur do et sur sol. Les chansons sont faites de ça.","es":"Has construido tus primeros acordes: tríadas apiladas 1-3-5, sobre do y sobre sol. Las canciones están hechas de esto.","it":"Hai costruito i tuoi primi accordi: triadi impilate 1-3-5, su do e su sol. Le canzoni sono fatte di questo."}}]}$cymbra$
),
(
  'sol-u7-04-majeur-ou-mineur', 'published', 'piano', 'solfege', 'advanced',
  'u7', $cymbra${"en":"Intervals, chords and ear","fr":"Intervalles, accords et oreille","es":"Intervalos, acordes y oído","it":"Intervalli, accordi e orecchio"}$cymbra$, 704, 2,
  $cymbra${"en":"Major or minor","fr":"Majeur ou mineur","es":"Mayor o menor","it":"Maggiore o minore"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u7-04-majeur-ou-mineur","instrument":"piano","track":"solfege","level":"advanced","title":{"en":"Major or minor","fr":"Majeur ou mineur","es":"Mayor o menor","it":"Maggiore o minore"},"summary":{"en":"Hear how the third turns a chord major or minor","fr":"Entendre comment la tierce rend un accord majeur ou mineur","es":"Escuchar cómo la tercera hace un acorde mayor o menor","it":"Sentire come la terza rende un accordo maggiore o minore"},"blocks":[{"type":"text","text":{"en":"Same pillars, one tiny move: lower the middle note and the chord turns from bright to shadowed. The third decides the colour.","fr":"Mêmes piliers, un tout petit geste : abaisse la note du milieu et l'accord passe de lumineux à voilé. C'est la tierce qui décide de la couleur.","es":"Los mismos pilares, un gesto mínimo: baja la nota del medio y el acorde pasa de luminoso a sombrío. La tercera decide el color.","it":"Stessi pilastri, un gesto minuscolo: abbassa la nota di mezzo e l'accordo passa da luminoso a ombroso. È la terza a decidere il colore."}},{"type":"earChoice","harmonic":true,"notes":["C4","E4","G4"],"answerId":"major","choices":[{"id":"major","label":{"en":"Major","fr":"Majeur","es":"Mayor","it":"Maggiore"}},{"id":"minor","label":{"en":"Minor","fr":"Mineur","es":"Menor","it":"Minore"}}],"prompt":{"en":"Listen to the three notes ring together. Bright and open — major or minor?","fr":"Écoute les trois notes sonner ensemble. Lumineux et ouvert — majeur ou mineur ?","es":"Escucha las tres notas sonando juntas. Luminoso y abierto: ¿mayor o menor?","it":"Ascolta le tre note che suonano insieme. Luminoso e aperto: maggiore o minore?"}},{"type":"earChoice","harmonic":true,"notes":["C4","Eb4","G4"],"answerId":"minor","choices":[{"id":"major","label":{"en":"Major","fr":"Majeur","es":"Mayor","it":"Maggiore"}},{"id":"minor","label":{"en":"Minor","fr":"Mineur","es":"Menor","it":"Minore"}}],"prompt":{"en":"Same chord, but the middle note slid down. How does it sound now?","fr":"Le même accord, mais la note du milieu a glissé vers le bas. Comment sonne-t-il maintenant ?","es":"El mismo acorde, pero la nota del medio bajó. ¿Cómo suena ahora?","it":"Lo stesso accordo, ma la nota di mezzo è scesa. Come suona adesso?"}},{"type":"buildChord","notes":["C4","Eb4","G4"],"prompt":{"en":"Lower the third yourself: build C, E flat, G and feel the minor colour under your fingers.","fr":"Abaisse la tierce toi-même : construis do, mi bémol, sol et sens la couleur mineure sous tes doigts.","es":"Baja tú la tercera: construye do, mi bemol, sol y siente el color menor bajo tus dedos.","it":"Abbassa tu la terza: costruisci do, mi bemolle, sol e senti il colore minore sotto le dita."}},{"type":"question","prompt":{"en":"Between C major and C minor, which note changes?","fr":"Entre do majeur et do mineur, quelle note change ?","es":"Entre do mayor y do menor, ¿qué nota cambia?","it":"Tra do maggiore e do minore, quale nota cambia?"},"options":[{"en":"The third — E becomes E flat","fr":"La tierce — mi devient mi bémol","es":"La tercera: mi se vuelve mi bemol","it":"La terza: mi diventa mi bemolle"},{"en":"The fifth — G moves down","fr":"La quinte — sol descend","es":"La quinta: sol baja","it":"La quinta: sol scende"}],"answerIndex":0,"feedback":{"en":"Exactly — the root and the fifth stay put; that one semitone repaints the whole chord.","fr":"Exactement — la fondamentale et la quinte ne bougent pas ; ce seul demi-ton repeint tout l'accord.","es":"Exacto: la fundamental y la quinta no se mueven; ese único semitono repinta todo el acorde.","it":"Esatto: la fondamentale e la quinta restano ferme; quel solo semitono ridipinge tutto l'accordo."}},{"type":"text","text":{"en":"Major or minor is one note's decision: the third. Your ear caught it — that colour will follow you into every piece you play.","fr":"Majeur ou mineur, c'est la décision d'une seule note : la tierce. Ton oreille l'a saisi — cette couleur t'accompagnera dans chaque morceau.","es":"Mayor o menor es la decisión de una sola nota: la tercera. Tu oído lo captó — ese color te acompañará en cada pieza.","it":"Maggiore o minore è la decisione di una sola nota: la terza. Il tuo orecchio l'ha colto — quel colore ti accompagnerà in ogni brano."}}]}$cymbra$
),
(
  'sol-u7-05-les-trois-piliers', 'published', 'piano', 'solfege', 'advanced',
  'u7', $cymbra${"en":"Intervals, chords and ear","fr":"Intervalles, accords et oreille","es":"Intervalos, acordes y oído","it":"Intervalli, accordi e orecchio"}$cymbra$, 705, 2,
  $cymbra${"en":"C, F, G: the three pillars","fr":"Do, fa, sol : les trois piliers","es":"Do, fa, sol: los tres pilares","it":"Do, fa, sol: i tre pilastri"}$cymbra$,
  $cymbra${"schemaVersion":2,"id":"sol-u7-05-les-trois-piliers","instrument":"piano","track":"solfege","level":"advanced","title":{"en":"C, F, G: the three pillars","fr":"Do, fa, sol : les trois piliers","es":"Do, fa, sol: los tres pilares","it":"Do, fa, sol: i tre pilastri"},"summary":{"en":"Own the C, F and G chords","fr":"Maîtriser les accords de do, fa et sol","es":"Dominar los acordes de do, fa y sol","it":"Padroneggiare gli accordi di do, fa e sol"},"blocks":[{"type":"text","text":{"en":"Take the major triad and plant it on C, on F and on G: chords I, IV and V. Three pillars that hold up thousands of songs.","fr":"Prends la triade majeure et plante-la sur do, sur fa et sur sol : les accords I, IV et V. Trois piliers qui portent des milliers de chansons.","es":"Toma la tríada mayor y plántala sobre do, sobre fa y sobre sol: los acordes I, IV y V. Tres pilares que sostienen miles de canciones.","it":"Prendi la triade maggiore e piantala su do, su fa e su sol: gli accordi I, IV e V. Tre pilastri che reggono migliaia di canzoni."}},{"type":"buildChord","notes":["F4","A4","C5"],"prompt":{"en":"The F chord: build F, A and C together — same 1-3-5 shape, new home.","fr":"L'accord de fa : construis fa, la et do ensemble — même forme 1-3-5, nouvelle maison.","es":"El acorde de fa: construye fa, la y do juntos — la misma forma 1-3-5, nueva casa.","it":"L'accordo di fa: costruisci fa, la e do insieme — stessa forma 1-3-5, nuova casa."}},{"type":"buildChord","notes":["G4","B4","D5"],"prompt":{"en":"Now the G chord: G, B and D — you built it before, make it ring again.","fr":"Maintenant l'accord de sol : sol, si et ré — tu l'as déjà construit, fais-le sonner à nouveau.","es":"Ahora el acorde de sol: sol, si y re — ya lo construiste antes, hazlo sonar otra vez.","it":"Ora l'accordo di sol: sol, si e re — l'hai già costruito, fallo risuonare di nuovo."}},{"type":"question","prompt":{"en":"What can you play with just the C, F and G chords?","fr":"Que peux-tu jouer avec seulement les accords de do, fa et sol ?","es":"¿Qué puedes tocar solo con los acordes de do, fa y sol?","it":"Cosa puoi suonare con i soli accordi di do, fa e sol?"},"options":[{"en":"Thousands of songs, from folk to pop","fr":"Des milliers de chansons, du folk à la pop","es":"Miles de canciones, del folk al pop","it":"Migliaia di canzoni, dal folk al pop"},{"en":"Almost nothing — real songs avoid them","fr":"Presque rien — les vraies chansons les évitent","es":"Casi nada: las canciones de verdad los evitan","it":"Quasi niente: le canzoni vere li evitano"}],"answerIndex":0,"feedback":{"en":"Yes — I, IV and V are the backbone of countless tunes, and you now own all three.","fr":"Oui — I, IV et V sont la colonne vertébrale d'innombrables mélodies, et tu possèdes désormais les trois.","es":"Sí: I, IV y V son la columna vertebral de infinidad de melodías, y ya dominas los tres.","it":"Sì: I, IV e V sono la spina dorsale di innumerevoli melodie, e ora li possiedi tutti e tre."}},{"type":"earChoice","harmonic":true,"notes":["F4","A4","C5"],"answerId":"major","choices":[{"id":"major","label":{"en":"Major","fr":"Majeur","es":"Mayor","it":"Maggiore"}},{"id":"minor","label":{"en":"Minor","fr":"Mineur","es":"Menor","it":"Minore"}}],"prompt":{"en":"Listen to the F chord ring. Same recipe as C — what colour is it?","fr":"Écoute sonner l'accord de fa. Même recette que do — quelle est sa couleur ?","es":"Escucha sonar el acorde de fa. La misma receta que do: ¿de qué color es?","it":"Ascolta suonare l'accordo di fa. Stessa ricetta di do: di che colore è?"}},{"type":"text","text":{"en":"C, F, G — three major triads, three pillars. With them under your hands, whole songbooks open up.","fr":"Do, fa, sol — trois triades majeures, trois piliers. Avec eux sous les doigts, des répertoires entiers s'ouvrent à toi.","es":"Do, fa, sol — tres tríadas mayores, tres pilares. Con ellos bajo tus manos se abren cancioneros enteros.","it":"Do, fa, sol — tre triadi maggiori, tre pilastri. Con loro sotto le mani si aprono interi canzonieri."}}]}$cymbra$
),
